function applyAction(type,args,next,committed=false){
 try{const before=state;const previous=state.location;const trip=type==='depart'?journeyPlan(args.destination,false):before.voyage&&!next.voyage&&!next.fleetLoss?continuedJourneyPlan(before,next):null;state=next;if(type==='battle-continue'){closeModal(true);screen='station';venueID='market';contactID='';}if(modalKind==='establishment'){const receipt=establishmentReceipt(type,args,before,next);if(receipt)updateEstablishmentFeedback(receipt);}if(['buy','sell','buy-max','sell-all'].includes(type))marketQuantities.clear();collectArrivalInspections(before,next);audio.action(type,args,before,next);if(type==='battle-order'||type==='battle-tick'){const scene=E.combatScene(before,next,type==='battle-tick'?{...args,live:true}:args);if(type==='battle-tick'&&!next.battle)scene.shots=[];battleFX={scene,at:performance.now()};}if(state.location!==previous){venueID='market';contactID='';screen='station';}if(state.location!==previous&&destination===state.location){destination=previous;selectedSystem=E.port(destination).group;}if(state.location!==previous&&E.freightOverview(state).jobs.some(c=>c.destination===state.location&&c.aboard>=c.quantity))tab='Contracts';if(type==='accept'){destination=E.activeContracts(state).find(c=>c.id===args.id).destination;selectedSystem=E.port(destination).group;}const priorAccess=new Set(E.accessiblePorts(before)),opened=E.accessiblePorts(next).filter(id=>!priorAccess.has(id));if(opened.length)toast('Access licensed: '+opened.map(id=>stationLabel(id)).join(', '));else if(type==='deliver')toast('Delivery completed.');const saved=committed?true:persist();if(committed)saveState=sharedStatus();if(trip){trip.saved=saved;trip.encounter=next.incident?{kind:next.incident.kind,phase:next.incident.phase||'approach',progress:next.incident.progress??.98}:null;}const localBattle=['battle-order','battle-tick','battle-plan'].includes(type)&&before.battle&&next.battle&&before.battle.id===next.battle.id&&before.flagshipID===next.flagshipID&&before.fleet?.length===next.fleet?.length&&screen==='battle'&&!modalKind;const localTrade=['buy','sell','buy-max','sell-all'].includes(type)&&previous===state.location&&screen==='station'&&modalKind==='establishment'&&venueID==='market'&&!state.incident&&!state.battle&&!state.fleetLoss;const localDock=['refuel','service-ship','service-all-ships','dry-dock-service'].includes(type)&&previous===state.location&&screen==='station'&&modalKind==='establishment'&&venueID==='shipyard'&&!state.incident&&!state.battle&&!state.fleetLoss;const localBank=['deposit','withdraw','borrow','repay','repay-local'].includes(type)&&previous===state.location&&screen==='station'&&modalKind==='establishment'&&venueID==='bank'&&!state.incident&&!state.battle&&!state.fleetLoss;const localWarehouse=['warehouse-store','warehouse-take'].includes(type)&&previous===state.location&&screen==='station'&&modalKind==='establishment'&&venueID==='warehouse'&&!state.incident&&!state.battle&&!state.fleetLoss;if(localBattle&&refreshSidebarStats()){updateSaveLabel();renderBattleScreen();}else if(localBank&&refreshSidebarStats()){updateSaveLabel();/* The bank-action handler refreshes the desk once after clearing the acknowledged amount. */}else if((localTrade||localDock||localWarehouse)&&refreshSidebarStats()){updateSaveLabel();if(localDock){if(!dockServicePending)refreshDockServices();}else if(localWarehouse){warehouseLot=1;refreshWarehouseConsole();}else if(!refreshMarketAfterTrade())refreshVisitModal();scheduleMainModal();}else render();if(state.location!==previous)window.scrollTo({top:0,left:0,behavior:'instant'});if(trip)showJourney(trip);else if(state.incident&&!(['battle-order','battle-tick','battle-plan'].includes(type)&&state.battle&&screen==='battle'))showEncounter();else if(modalKind==='encounter')closeModal();announceCommodityUnlocks(before,next);scheduleInspectionNotice();scheduleCharterNotice();return true;}catch(error){toast(error.message);const el=$('dialog-error');if(el)el.textContent=error.message;return false;}
}
// One cached renderer, including a local shadow map; no remote textures or runtime.
