 const services=$('modal').querySelector('.dock-console');if(!services)return false;
 const currentFocus=focusID||document.activeElement?.id,top=services.querySelector('.dock-content').scrollTop,opened=new Set([...services.querySelectorAll('details[open]')].map(el=>el.id));services.outerHTML=dryDockPanel();$('modal').querySelectorAll('.dock-console details').forEach(el=>el.open=opened.has(el.id));$('modal').querySelector('.dock-content').scrollTop=resetScroll?0:top;const focus=$(currentFocus==='dock-load'?'dock-tonnes':currentFocus);if(focus&&!focus.disabled)focus.focus({preventScroll:true});else $('dock-selection')?.focus({preventScroll:true});return true;
