 for(const r of state.reputationRumors||[])add('Reputation report','Word from '+E.port(r.origin).name,`Day ${r.sourceDay}: ${r.reason}\nLocal trust ${r.localChange>0?'+':''}${r.localChange}; wider reputation ${r.publicChange>0?'+':''}${r.publicChange}. Positive progress may contribute to a later point.`,r.day,stationLabel(r.port));
