 const discoveries=new Map();for(const r of E.commodityJournal(state).history){const key=r.day+':'+r.port;if(!discoveries.has(key))discoveries.set(key,{...r,names:[]});discoveries.get(key).names.push(r.name);}for(const r of discoveries.values())add('Commodity discovery','New goods available',r.names.join(', '),r.day,r.station);
 const licences=E.charterProgress(state);for(const r of state.licences||[])add('Port authority',licences.find(l=>l.id===r.id)?.name||'Access licence',`Licence issued${r.cost?' · '+fmt(r.cost)+' cr':''}.`,r.day,r.issuer?E.port(r.issuer).name:'');
 for(const r of E.diplomaticOverview(state).history)add('Diplomacy',r.title,[r.status,r.summary,r.choiceTitle?'Position: '+r.choiceTitle:''].filter(Boolean).join('\n'),r.closedDay,r.station);
 const missions=E.missionJournal(state);for(const r of missions.receipts)add('Assignment receipt','Objective recorded',r.text,r.day,r.port?E.port(r.port).name:'');
 for(const r of missions.history)add('Assignment',r.title,[r.status,r.summary||r.outcome||''].filter(Boolean).join('\n'),r.closedDay,r.station);
 for(const r of E.civilianOverview(state).history)add('Specialist work','Work recorded',r.text,r.day,r.port?E.port(r.port).name:'');
 for(const r of E.underworldOverview(state).quests.filter(q=>q.status!=='active'))add('Private assignment',r.title,'Assignment '+r.status+'.',r.completedDay,r.originName);
