 for(const r of state.blockadeWorld?.stations||[])if(r.clearedDay!==null&&!state.blockades?.jobs.some(j=>j.destination===r.port))add('Station liberation','Liberated '+E.port(r.port).name,'Raiders defeated before docking. Temporary local exchange recovery premiums opened.',r.clearedDay,stationLabel(r.port));
