function maybeLoadJournalHistory(v){
 if(journalView===v&&modalKind==='utility'&&tab==='Log'&&v.status.getBoundingClientRect().top<=v.pane.getBoundingClientRect().bottom+Math.max(1000,v.pane.clientHeight*2))loadJournalHistory();
}
async function loadJournalHistory(){
 const key=journalHistoryKey();if(!key)return;
 if(journalHistory.key!==key)Object.assign(journalHistory,{key,rows:[],before:null,busy:false,done:false,error:''});
 if(journalHistory.busy||journalHistory.done||journalHistory.error)return;const generation=journalHistory.generation;journalHistory.busy=true;renderJournalHistory();
 try{
  await actionQueue;if(journalHistory.generation!==generation||journalHistoryKey()!==key)return;
  const result=await J.readPage(sharedSession,journalHistory.before,journalFeedContext());
  if(journalHistory.generation!==generation||journalHistoryKey()!==key)return;
  if(result.more&&(!Number.isSafeInteger(result.before)||result.before<1||(journalHistory.before!==null&&result.before>=journalHistory.before)))throw Error('Earlier entries could not be loaded. Retry to continue.');
  const seen=new Set(journalHistory.rows.filter(r=>r.sequence).map(r=>r.sequence));
  for(const r of result.records){
   if(seen.has(r.sequence))continue;
   journalHistory.rows.push(r);seen.add(r.sequence);
  }
  if(result.imported)journalHistory.rows.push(...journalLegacyRecords(result.imported).map(r=>({...r,preLedger:true})));
  if(!result.more)journalHistory.done=true;journalHistory.before=result.before||journalHistory.before;
 }catch(error){if(journalHistory.generation===generation&&journalHistoryKey()===key)journalHistory.error='Earlier entries are temporarily unavailable. Retry to continue; recorded progress is preserved.';}
 finally{if(journalHistory.generation===generation&&journalHistoryKey()===key){journalHistory.busy=false;renderJournalHistory();const v=journalView;if(v&&!journalHistory.error&&!journalHistory.done)requestAnimationFrame(()=>maybeLoadJournalHistory(v));}}
}
function mountJournalHistory(){
 stopJournalHistory();const key=journalHistoryKey();if(!key)return;
 if(journalHistory.key!==key)Object.assign(journalHistory,{key,rows:[],before:null,busy:false,done:false,error:''});journalHistory.error='';
 const pane=$('modal').querySelector('.utility-content'),status=pane?.querySelector('[data-journal-status]');if(!status)return;
 const v=journalView={key,pane,status,list:pane.querySelector('.journal-ledger'),retry:pane.querySelector('[data-action="journal-retry"]'),rendered:0,observer:null,window:null};
 v.window=SpacetraderJournalWindow.create({pane,list:v.list,renderRow:journalRowHTML,onScroll:()=>maybeLoadJournalHistory(v)});
 if(typeof IntersectionObserver!=='undefined'){v.observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))maybeLoadJournalHistory(v);},{root:pane,rootMargin:'240px'});v.observer.observe(status);}
 renderJournalHistory();loadJournalHistory();
}

