// Shared by every disclosure and popout. Outside presses never activate the
// background, and a drag that starts inside a dialog cannot dismiss it.
// Scope popouts to the main pane; the sidebar remains an interactive navigation island.
function mainModalBounds(rect,width,height){const left=Math.max(0,Math.min(width-1,rect?.left||0)),right=Math.max(left+1,Math.min(width,rect?.right??width));let top=Math.max(0,Math.min(height-1,rect?.top||0)),bottom=Math.max(top+1,Math.min(height,rect?.bottom??height));if(bottom-top<120){top=0;bottom=height;}return {left,top,right:width-right,bottom:height-bottom,width:right-left,height:bottom-top,x:(left+right)/2,y:(top+bottom)/2};}
function mainModalPosition(bounds,size,ratio=1){const pixels=Number.isFinite(ratio)&&ratio>0?ratio:1,snap=value=>Math.round(value*pixels)/pixels;return {left:snap(bounds.x-size.width/2),top:snap(bounds.y-size.height/2)};}
