function installTileInteractions(doc,dialog,getKind,close){
 let outsidePress=null;
 const protectedKinds=new Set(['encounter','journey','new','abandon','theft','ship-exchange']);
 const dismissible=()=>!protectedKinds.has(getKind())||getKind()==='new'&&dialog.dataset.menuParent==='true';
 const outside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;};
 doc.addEventListener('pointerdown',e=>{
  if(e.button!==0)return;
  // A summary must receive its click before sibling collapse can move it.
  if(!e.target.closest?.('summary'))doc.querySelectorAll('details[open]').forEach(tile=>{if(!tile.contains(e.target))tile.open=false;});
  outsidePress=dialog.open&&(e.target===dialog||e.target.id==='modal-shade')&&outside(e)&&dismissible()?{id:e.pointerId,kind:getKind(),version:dialog.dataset.presentation}:null;
 },true);
 doc.addEventListener('click',e=>{
  if(e.target.closest?.('summary'))doc.querySelectorAll('details[open]').forEach(tile=>{if(!tile.contains(e.target))tile.open=false;});
 },true);
 doc.addEventListener('pointerup',e=>{
  const press=outsidePress;outsidePress=null;
  if(press&&e.button===0&&press.id===e.pointerId&&dialog.open&&press.kind===getKind()&&press.version===dialog.dataset.presentation&&(e.target===dialog||e.target.id==='modal-shade')&&outside(e)&&dismissible())close();
 },true);
 doc.addEventListener('pointercancel',()=>{outsidePress=null;},true);
}
let menuPopoutRestoring=false;
const menuPopoutParents=[],menuPopoutKinds=new Set(['story','audio','ledger','ledger-confirm','checkpoints','checkpoint-replace','checkpoint-delete','checkpoint-load-confirm','backups','new']);
function clearMenuPopouts(){menuPopoutParents.length=0;}
function trackMenuPopout(kind){
 if(menuPopoutRestoring)return;
 if(kind==='menu'||!menuPopoutKinds.has(kind)){clearMenuPopouts();return;}
 if(kind===modalKind)return;
 const previous=menuPopoutParents.findLastIndex(frame=>frame.kind===kind);
 if(previous>=0){menuPopoutParents.splice(previous);return;}
 const dialog=$('modal'),frame={kind:modalKind,mode:checkpointMenuMode,scroll:dialog.scrollTop,positions:[...dialog.querySelectorAll('.utility-content,.drive-archive,.audio-settings')].map(el=>el.scrollTop),focus:document.activeElement?.dataset?{...document.activeElement.dataset}:null};
 if(modalKind==='menu'||menuPopoutKinds.has(modalKind))menuPopoutParents.push(frame);
 else menuPopoutParents.push({kind:'menu',scroll:0,positions:[]});
 if(menuPopoutParents.length>10)menuPopoutParents.splice(1,1);
}
function returnMenuPopout(){
 const frame=menuPopoutParents.pop();if(!frame)return false;
 pendingCheckpoint=null;pendingLoad=null;menuPopoutRestoring=true;
 try{
  if(frame.kind==='menu')showGameMenu();
  else if(frame.kind==='story')showDriveStory();
  else if(frame.kind==='audio')showAudioSettings();
  else if(frame.kind==='ledger')showLedger();
  else if(frame.kind==='checkpoints')showCheckpointMenu(frame.mode);
  else if(frame.kind==='backups')restoreBackup();
  else showGameMenu();
 }finally{menuPopoutRestoring=false;}
 const dialog=$('modal');dialog.scrollTop=frame.scroll||0;[...dialog.querySelectorAll('.utility-content,.drive-archive,.audio-settings')].forEach((el,i)=>el.scrollTop=frame.positions?.[i]||0);
 if(frame.focus)[...dialog.querySelectorAll('[data-action]')].find(el=>Object.entries(frame.focus).every(([k,v])=>el.dataset[k]===v))?.focus({preventScroll:true});
 return true;
}
let modalPresentation=0,modalReturnTarget=null;
