 stopLedgerHistory();stopJournalHistory();conversationRevealer.stop();positionMainModal();const notice=$('commodity-unlock-notice');notice?.remove();stopFleetPreviews();
 const active=document.activeElement;if(active&&!$('modal').contains(active))modalReturnTarget=active;
 if(kind!=='portrait')portraitReturn=false;
 $('modal').classList.remove('battle-dialog','journey-dialog','drive-dialog','station-detail-dialog','establishment-dialog','utility-dialog','game-menu-dialog','fleet-overview-dialog','portrait-dialog','audio-dialog','inspection-dialog','records-dialog','guide-dialog','report-dialog','market-price-dialog');modalKind=kind;$('modal').dataset.menuParent=String(menuPopoutParents.length>0);$('modal').dataset.presentation=String(++modalPresentation);$('modal').innerHTML=html;
 if(!$('modal').open)$('modal').show();$('modal').setAttribute('aria-modal','false');syncPopoutScope();$('modal').scrollTop=0;if(notice)$('modal').appendChild(notice);scheduleMainModal();mountConversationResponses();focusPopout();syncAudioScene();
