function popoutKeydown(e){
 const dialog=$('modal');if(!dialog.open)return;
 if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dialog.dispatchEvent(new Event('cancel',{cancelable:true}));return;}
 if(e.key!=='Tab')return;
 const nodes=[...document.querySelectorAll('.game-shell>aside button,.game-shell>aside a[href],#modal button,#modal input,#modal select,#modal textarea,#modal a[href],#modal summary,#modal [tabindex="0"]')].filter(el=>!el.disabled&&!el.closest('[inert]')&&el.getClientRects().length&&el.tabIndex>=0);
 const first=nodes[0],last=nodes.at(-1),active=document.activeElement;
 if(!first){e.preventDefault();dialog.focus();return;}
 if(!nodes.includes(active)||e.shiftKey&&active===first||!e.shiftKey&&active===last){e.preventDefault();(e.shiftKey?last:first).focus({preventScroll:true});}
}
document.addEventListener('keydown',popoutKeydown);
let portraitReturn=false,marketPriceReturn=null;
