function marketPriceChart(model,name){
 if(model.restricted)return '<p class="muted">This dealer uses negotiated prices. Available stock and buying limits still apply.</p>';
 const points=model.points,width=660,height=300,left=60,right=18,top=22,bottom=44,plotW=width-left-right,plotH=height-top-bottom,values=points.flatMap(p=>[p.buy,p.sell]),lo=Math.min(...values),hi=Math.max(...values),pad=Math.max(1,(hi-lo)*.08),min=Math.max(0,lo-pad),max=hi+pad,x=q=>left+Math.max(0,Math.min(1,q/model.capacity))*plotW,y=p=>top+plotH-(p-min)/(max-min)*plotH;
 const grid=Array.from({length:5},(_,i)=>{const price=min+(max-min)*i/4;return `<line x1="${left}" x2="${width-right}" y1="${y(price)}" y2="${y(price)}"/><text x="${left-8}" y="${y(price)+4}" text-anchor="end">${fmt(Math.round(price))}</text>`;}).join('');
 const paths=['buy','sell'].map(side=>`<path class="price-curve-${side}" d="${points.map((p,i)=>(i?'L':'M')+x(p.quantity).toFixed(2)+','+y(p[side]).toFixed(2)).join(' ')}"/>`).join('');
 return `<svg class="market-price-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(name)} buy and sell prices across station reserves, from empty to full"><g class="price-curve-grid">${grid}</g>${paths}<line class="price-current" x1="${x(model.quantity)}" x2="${x(model.quantity)}" y1="${top}" y2="${height-bottom}"/><circle class="price-current-buy" cx="${x(model.quantity)}" cy="${y(model.quote.buy)}" r="4"/><circle class="price-current-sell" cx="${x(model.quantity)}" cy="${y(model.quote.sell)}" r="4"/><text x="${left}" y="${height-20}">Empty</text><text x="${left+plotW/2}" y="${height-20}" text-anchor="middle">50%</text><text x="${width-right}" y="${height-20}" text-anchor="end">Full</text><text x="${left}" y="13">cr / lot</text></svg>`;
}
