// Preserve the confirmation button between recorded orders. Replacing the whole
// establishment can otherwise remove a fast second click between pointer events.
function patchMarketNode(current,next){
 const element=current.nodeType===1;
 if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName||element&&['marketProduct','action','id'].some(k=>current.dataset?.[k]!==next.dataset?.[k])){current.replaceWith(next.cloneNode(true));return;}
 if(!element){if(current.nodeValue!==next.nodeValue)current.nodeValue=next.nodeValue;return;}
 for(const attr of [...current.attributes])if(!next.hasAttribute(attr.name))current.removeAttribute(attr.name);
 for(const attr of [...next.attributes])if(current.getAttribute(attr.name)!==attr.value)current.setAttribute(attr.name,attr.value);
 const children=[...next.childNodes];for(let i=0;i<children.length;i++){if(current.childNodes[i])patchMarketNode(current.childNodes[i],children[i]);else current.appendChild(children[i].cloneNode(true));}
 while(current.childNodes.length>children.length)current.lastChild.remove();
 if((current.tagName==='INPUT'||current.tagName==='SELECT')&&current.value!==next.value)current.value=next.value;
}
