 input.setAttribute('aria-invalid',String(!valid));if(valid)marketQuantities.set(id,n);const unitPrice=article.querySelector('[data-market-unit-price]');if(unitPrice)unitPrice.textContent=marketOrderUnitPrice(id,n,marketMode());const q=E.marketState(state,id),limits=E.marketOrderLimits(state,id,q,marketDeliveryFrom(article),marketSourceFrom(article));
 for(const action of ['buy','sell']){const b=article.querySelector(`[data-action="${action}"]`);if(!b)continue;const total=E.tradeTotal(state,g.id,n,action==='buy');b.disabled=!valid||n>(action==='buy'?limits.buyMax:limits.sellAll);b.firstChild.nodeValue=action==='buy'?'Buy':'Sell';b.title=valid?`${action==='buy'?'Buy':'Sell'} ${n} units for ${fmt(total)} cr`:'Enter a whole number of units';b.setAttribute('aria-label',valid?`${action==='buy'?'Buy':'Sell'} ${n} ${g.name} for ${fmt(total)} credits`:b.title);article.querySelector('.exchange-total strong').textContent=valid?marketCompactTotal(total)+' cr':'—';}
 article.querySelector('[data-delta="-1"]').disabled=valid&&n<=1;article.querySelector('[data-delta="1"]').disabled=!valid||n>=Math.max(1,marketMode()==='buy'?limits.buyMax:limits.sellAll);
 article.querySelector('.market-profit').innerHTML=valid&&marketMode()==='sell'?marketMarginHTML(E.saleAssessment(state,id,n,state.location,marketSourceFrom(article))):'';
 const feedback=article.querySelector('[data-market-feedback]'),maximum=marketMode()==='buy'?limits.buyMax:limits.sellAll;if(feedback){feedback.textContent=!valid?'Enter a whole number from 1 to 32,000.':n>maximum?(feedback.dataset.baseReason||`Maximum available: ${maximum} units.`):feedback.dataset.baseReason;feedback.classList.toggle('sr-only',valid&&n<=maximum||maximum===0&&valid);}
