function freightReadyToDeliver(c){return c.destination===state.location&&c.aboard>=c.quantity&&state.day<=c.deadline;}
function sortFreightDeliveries(rows,active=false,distances=new Map()){
 const distance=id=>{if(!distances.has(id))distances.set(id,id===state.location?0:E.routeTransfer(state,id).distanceKM);return distances.get(id);};
 const ranked=rows.map((row,index)=>({row,index,ready:active&&freightReadyToDeliver(row),distance:distance(row.destination)}));
 ranked.sort((a,b)=>Number(b.ready)-Number(a.ready)||a.distance-b.distance||a.row.deadline-b.row.deadline||a.index-b.index);
 return ranked.map(v=>v.row);
}
function freightPanel(){
 const status=E.freightOverview(state),pool=E.fleetOverview(state),distances=new Map(),jobs=sortFreightDeliveries(status.jobs,true,distances),offers=sortFreightDeliveries(E.offers(state),false,distances);
 const detail=d=>`<h4>${esc(d.tierName||'Freight')}</h4><ul class="freight-products">${E.freightLines(d).map(l=>`<li>${l.quantity} × ${esc(E.goods.find(g=>g.id===l.good).name)}</li>`).join('')}</ul><p class="freight-destination">To <strong>${esc(E.port(d.destination).name)}</strong> · ${esc(stationLabel(d.destination,false))}</p><p class="freight-offer-meta"><strong>${d.pricing?.version===2?'Up to ':''}${fmt(d.reward)} cr</strong><span>${esc(serviceDeadline(d.deadline))}</span><span>${(d.quantity*.25).toLocaleString(undefined,{maximumFractionDigits:2})} t</span>${d.pricing?`<span>${esc(d.pricing.riskLabel)} · ${Math.round(d.pricing.risk*100)}% ${d.acceptedDay!==undefined?'at booking':'voyage risk'}</span>`:''}</p>${d.pricing?.version===2?`<p class="small muted">${fmt(d.pricing.commission)} cr commission · up to ${fmt(d.pricing.expenses)} cr recorded route expenses</p>`:''}`;
 const available=`<div class="freight-list-heading"><h3>${offers.length?'Available deliveries':'No freight available'}</h3><span>${(pool.freeUnits*.25).toLocaleString(undefined,{maximumFractionDigits:2})} t free</span></div>${offers.map(d=>`<article class="card freight-offer" data-offer-id="${esc(d.id)}">${detail(d)}${btn('Accept & load freight','accept',`data-id="${esc(d.id)}"`,!d.canAccept)}${!d.canAccept?`<p class="freight-space">${esc(d.reason||'Make room for the entire shipment.')}</p>`:''}</article>`).join('')||(!status.suspensionDays&&status.board.nextRefresh!==null?`<p class="muted">New offers in ${status.board.remaining} days.</p>`:'')}`;
 return `<div class="compact-freight-board">${status.jobs.length?'<h3>Active deliveries</h3>':''}${jobs.map(c=>`<article class="card freight-offer" data-contract-id="${esc(c.id)}">${detail(c)}<p class="freight-progress">${c.aboard} / ${c.quantity} shipment units aboard</p>${c.fulfilment!=='consignment'?'<p class="small muted">Use your owned cargo for this existing purchase contract.</p>':''}<div class="actions">${btn('Deliver · '+fmt(c.payable??c.reward)+' cr','deliver',`data-id="${esc(c.id)}"`,!freightReadyToDeliver(c),'primary')}${c.destination!==state.location?btn('Plot destination','plot',`data-id="${c.destination}"`):''}</div><div class="freight-secondary">${btn('Abandon delivery…','abandon-contract',`data-id="${esc(c.id)}"`,false,'danger')}${c.supplied?btn('Steal client cargo…','steal-freight',`data-id="${esc(c.id)}"`,!c.theft.canSteal,'danger'):''}</div>${c.supplied&&c.theft.reason?`<p class="small muted">${esc(c.theft.reason)}</p>`:''}</article>`).join('')}${status.returns.length?'<h3>Client cargo to return</h3>':''}${status.returns.map(c=>`<article class="card freight-offer"><h4>${esc(E.freightDescription(c))}</h4><p class="freight-progress">${c.aboard} sealed units · ${c.local} here</p><p class="small muted">Client-owned · no purchase cost or delivery payment</p>${btn('Return '+c.local+' units','return-freight',`data-id="${esc(c.id)}"`,!c.canReturn)}</article>`).join('')}${available}</div>`;
}

function captainAdvantagesHTML(){const a=E.captainAdvantages(state);return a?`<section class="captain-advantages" aria-label="Captain advantages"><h3>Captain advantages</h3><p><strong>${esc(a.background.name)}</strong><br>${esc(a.background.benefit)}</p><p><strong>${esc(a.disposition.name)}</strong><br>${esc(a.disposition.benefit)}</p></section>`:'';}
function skillProgressCard(k){const p=E.skillProgressForXP(state.profile.xp[k]);return `<div class="skill"><div class="gauge-label"><strong>${E.skillNames[k]}</strong><span>Level ${p.level} · ${fmt(p.xp)} XP</span></div><div class="track"><span style="width:${p.fraction*100}%"></span></div><p class="small muted">${p.next===null?'Maximum level reached':`Next level at ${fmt(p.next)} total XP · ${fmt(p.remaining)} more needed`}</p><small class="muted">${({commerce:'Earned by selling cargo and completing deliveries. Tracks trading experience. Daily market spreads use fixed availability tiers.',navigation:'Earned by voyages and route study. Records proficiency; never shortens physical transfer times.',engineering:'Earned by repairs and incident response. Reduces equipment-incident risk by 0.8 percentage point per level.',diplomacy:'Earned by first conversations, aid and negotiation. Adds 3.5 percentage points per level to negotiation success.'})[k]}</small></div>`;}
function captainStandingCard(c){const r=E.reputationData(c);return `<section class="light-note evolution" aria-label="Public reputation"><h3 style="color:${r.score>0?'#397866':r.score<0?'#9E473B':'#213C4B'}">${esc(r.label)} · ${r.score>0?'+':''}${r.score} / 100</h3><p class="small">${esc(r.detail)}</p>${r.score<100?`<p class="small">Next point: ${fmt(r.progress)} / ${fmt(r.required)} progress.${r.score>=r.ceiling?' More station support required.':''}</p>`:''}${!r.history.length?'<p class="small muted">Earlier completed deliveries, clinic aid and victories contribute to your standing. New changes appear here.</p>':r.history.slice(-6).reverse().map(v=>`<p class="small" style="color:${v.change>0?'#397866':'#9E473B'}">Day ${v.day} · ${v.change>0?'+':''}${v.change} · ${esc(v.reason)}</p>`).join('')}</section>`;}
function showCreator(){if(state.profile.created)return;const c=state.profile;openModal('creator',modalHead('Your independent charter')+`<p>Choose your captain’s background and outlook. Each background grants a starting skill level and a lasting specialty; your disposition adds another advantage. ${c.migrated?'Your existing voyage, money and cargo will be retained.':''}</p><p class="light-note">Your ${esc(E.ship(state).name)} is financed by a ${fmt(E.ship(state).price)} cr starter loan at 4% annual interest. You begin with ${fmt(state.credits)} cr in cash. The Earth bank’s starting credit limit is ${fmt(E.bankTerms('earth',state).creditLimit)} cr, including your loan.</p><form id="character-form"><div class="creator-identity"><div><label for="captain-name">Captain’s name</label><input id="captain-name" name="name" value="" maxlength="60" required></div><div><label for="captain-species">Species</label><select id="captain-species" name="species">${E.speciesCatalog.map(v=>`<option value="${v.id}" ${v.id===(c.species||'human')?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div></div><label for="background">Background</label><select id="background" name="background" aria-describedby="background-description">${Object.entries(E.skillNames).map(([skill,label])=>`<optgroup label="${esc(label)} careers">${Object.entries(E.backgrounds).filter(([,v])=>v.skill===skill).map(([k,v])=>`<option value="${k}" ${c.background===k?'selected':''}>${esc(v.name)}</option>`).join('')}</optgroup>`).join('')}</select><p id="background-description" class="creator-choice-description">${esc(E.backgrounds[c.background].description)} <strong>${esc(E.backgrounds[c.background].benefit)} Starting focus: ${esc(E.skillNames[E.backgrounds[c.background].skill])}.</strong></p><label for="temperament">Starting disposition</label><select id="temperament" name="temperament" aria-describedby="temperament-description">${['measured','bold','empathetic'].map(style=>`<optgroup label="${style==='measured'?'Thoughtful':style==='bold'?'Self-directed':'People-focused'} outlooks">${Object.entries(E.temperamentInfo).filter(([,v])=>v.style===style).map(([k,v])=>`<option value="${k}" ${c.temperament===k?'selected':''}>${esc(v.name)}</option>`).join('')}</optgroup>`).join('')}</select><p id="temperament-description" class="creator-choice-description">${esc(E.temperamentInfo[c.temperament].description)} <strong>${esc(E.temperamentInfo[c.temperament].benefit)}</strong></p><p class="muted">Your later choices shape your reputation and character.</p><p id="dialog-error" class="dialog-error"></p><button class="primary" type="submit">Sign the charter</button></form>`);}
function transitContextHTML(){
 const v=state.voyage;if(!v)return '';const progress=Math.round(v.progress*100);
 return `<section class="transit-contact" aria-label="Journey interrupted in transit"><p class="eyebrow">In transit · Journey interrupted</p><p class="transit-route"><strong>${esc(stationLabel(v.origin))}</strong><span aria-hidden="true">→</span><strong>${esc(stationLabel(v.destination))}</strong></p><div class="transit-route-track" role="img" aria-label="Interception at ${progress}% of the planned flight"><span style="width:${progress}%"></span><i style="left:${progress}%"></i></div><p class="transit-remaining">${progress}% through planned flight · ${fmt(v.remainingDays)} flight ${v.remainingDays===1?'day':'days'} to destination</p></section>`;
}
function showEncounter(){if(state.incident?.kind==='battle-summary'){showBattleReport();return;}if(state.incident?.kind==='blockade'){const i=state.incident,r=E.blockadeRecovery(state);openModal('encounter',modalHead('Blockade still holds',false)+`<p class="eyebrow">${esc(stationLabel(i.destination))}</p>${rich(i.detail)}${encounterOption('Resume liberation battle','Defeat every raider to open the station. No commission required.','fight')}${encounterOption('Withdraw to '+esc(stationLabel(r.port)),`Contracted fleet recovery: ${fmt(r.cost)} cr · ${fmt(r.days)} days. Unpaid recovery charges enter credit; the blockade remains. No docking or trading here.`,'withdraw')}<p id="dialog-error" class="dialog-error"></p>`);return;}if(state.incident?.kind==='asteroid'){showAsteroidEncounter();return;}if(state.battle){showBattle();return;}const i=state.incident;if(!i)return;const pirate=i.kind==='pirate',threat=pirate?E.combatAssessment(state):null;openModal('encounter',modalHead(esc(i.title),false)+`${state.voyage?transitContextHTML():`<p class="eyebrow">${pirate?'Approach security':'Engineering incident'} / ${esc(stationLabel(i.destination))}</p>`}${rich(i.detail)}${threat?`<p class="combat-advisory ${threat.ratio<.8?'danger':''}"><strong>${esc(threat.label)}</strong> · ${esc(threat.detail)}</p>${threat.warnings.slice(0,4).map(w=>`<p class="small service-warning">${esc(w.text)}</p>`).join('')}`:''}${pirate?`<p>Credits ${fmt(state.credits)} cr · remaining propellant ${dec(state.fuel)} t</p>${encounterOption('Engage the raiders','Begin a tactical battle with the flagship and assigned escorts. Ammunition, damage and decisions persist.','fight')}${encounterOption('Pay the demand',`Costs ${fmt(E.pirateFee(state))} cr. Guaranteed safe passage for this encounter.`,'pay',state.credits<E.pirateFee(state))}${encounterOption('Negotiate on an open channel',`One day to attempt talks. Success ${Math.round((E.negotiationChance(state,i.destination))*100)}%. On failure: half the fee (or remaining cash), 8 integrity and two extra days.`,'negotiate')}${encounterOption(i.phase==='route'?'Break contact and resume the route':'Use a guarded alternate approach',`A 0.25 km/s correction costs ${E.evasionFuel(state).toFixed(2)} t propellant and adds two days. Guaranteed escape from this contact; other threats can still occur.`,'evade',!E.canEvade(state))}${encounterOption('Request patrol assistance','No cash or propellant required. Adds seven days, loses 12 integrity and up to two cargo units.','distress')}`:`${encounterOption('Install a spare assembly','Uses one engineering spare and adds one day. No extra hull damage.','spare',state.spares===0)}${encounterOption('Isolate the damaged system',`Lose ${i.damage} integrity; add ${i.delay} days. No spare required.`,'isolate')}`}<p id="dialog-error" class="dialog-error"></p><p class="small muted">This decision will be recorded in your captain’s history.</p>`);}
function encounterOption(title,detail,choice,disabled=false){return btn(`<strong>${title}</strong><small>${detail}</small>`,'resolve',`data-choice="${choice}"`,disabled,'option');}
function establishmentGuideHTML(){
 const p=E.port(state.location),venues=E.establishments(p.id,false,state);
 return `<section class="info-section establishment-guide"><h3>Local establishments</h3><p>${esc(stationLabel(p))}</p>${venues.map(v=>`<details><summary>${esc(establishmentTitle(v.id))}</summary><p>${esc(establishmentDescription(v,p))}</p></details>`).join('')}</section>`;
}
