 if(window.__TAURI__?.core?.invoke){window.__TAURI__.core.invoke('open_guide').catch(()=>toast('Guide could not open. Visit http://127.0.0.1:8878/ in your browser.'));return;}
 window.open('http://127.0.0.1:8878/','_blank','noopener,noreferrer');
