 <div class="journey-readout"><div><p class="eyebrow" id="journey-stage" role="status" aria-live="polite"></p><strong id="journey-date"></strong><p class="small" id="journey-elapsed"></p></div><div class="journey-manifest"><strong>${fmt(plan.q.coastDays)} days in flight</strong><span>${plan.q.acceleration.toFixed(3)} m/s² · peak ${fmt(plan.q.peakSpeed)} km/s</span><span>${fmt(plan.q.waitDays)} days clearance · ${plan.q.deltaV.toFixed(2)} km/s Δv</span><span>${dec(plan.q.burn)} t fleet propellant · ${plan.escorts.length} escorts</span></div></div>
