let conversationOfferPreference=null;
function visibleMissionTopics(d){const q=d.tree.commission,settled=q&&q.status!=='active'&&q.status!=='offered';return d.topics.filter(t=>t.id!=='tree-receipt'&&!(t.id==='tree-back'&&d.topics.some(o=>o.id==='tree-patron-buy'))&&!(settled&&['tree-needs','tree-offer'].includes(t.id)));}
function commissionCardHTML(q){if(q.status!=='active'&&!(q.status==='offered'&&q.canAccept))return '';const progress=objectiveText(q.progress||''),reason=objectiveText(q.reason||'');return `<section class="dialogue-commission"><h3>${esc(q.title)}</h3><p>${esc(objectiveText(q.description))}</p><p><strong>${esc(objectiveTerms(q))}</strong></p>${privateProjectStepsHTML(q)}${q.status==='active'&&progress?`<p>${esc(progress)}</p>`:''}${reason&&reason!==progress?`<p>${esc(reason)}</p>`:''}</section>`;}

function privateProjectStepsHTML(q){return q.steps?.length?`<ol class="private-project-steps">${q.steps.map(x=>`<li><strong>${esc(x.task)}</strong><br>${esc(E.establishments(x.port,false,state).find(v=>v.id===x.venue)?.name||x.venue)} → ${esc(stationLabel(x.port||x.station))} → ${esc(x.person)}<br>${esc(objectiveCost(x))}${x.chosen?`<br>Approach: ${esc(x.chosen.name)}`:''}${x.doneDay!==null?`<br>Recorded on day ${x.doneDay}`:''}</li>`).join('')}</ol>`:'';}

function commodityJournalHTML(){
 const journal=E.commodityJournal(state),groups=new Map();
 for(const r of journal.history){const key=[r.day,r.port,r.skill,r.level].join(':');if(!groups.has(key))groups.set(key,{...r,names:[]});groups.get(key).names.push(r.name);}
 return `<section class="commodity-journal" aria-label="Commodity discoveries"><h3>Commodity discoveries</h3><p class="muted">Only visited exchanges are shown. Stock varies; specialist cargo needs a compatible hold or local warehouse.</p><details><summary>Unlocked commodities · ${journal.known.length}</summary><ul class="commodity-known">${journal.known.map(g=>`<li><strong>${esc(g.name)}</strong>${g.specialist?'<small>Specialist cargo</small>':''}<details class="commodity-stations"><summary>Visited exchanges · ${g.stations.length}</summary>${g.stations.length?`<ul class="commodity-station-list">${g.stations.map(p=>`<li class="commodity-station-row"><span class="commodity-station-place">${esc(p.name)}<small>${esc(stationLabel(p.id||p.name,false))}</small></span><span class="commodity-trade-direction">${p.stationSells?'Station buys &amp; sells':'Station buys only'}</span></li>`).join('')}</ul>`:'<p>No visited exchanges recorded.</p>'}</details></li>`).join('')}</ul></details>${groups.size?`<div class="commodity-discovery-history">${[...groups.values()].map(r=>`<article><h4>${esc(r.names.join(', '))}</h4><p>${date(r.day)} · day ${fmt(r.day)} · ${esc(stationLabel(r.port||r.station))}</p>${r.stage?'<p>Discovered through exploration and trading experience.</p>':'<p>'+esc(r.skillName)+' level '+r.level+'</p>'}</article>`).join('')}</div>`:'<p class="small muted">New discoveries will be recorded here as you gain experience. Your currently unlocked commodities are listed above.</p>'}</section>`;
}
function tradeRumorJournalHTML(){
 const rows=E.tradeRumorJournal(state),card=r=>`<article class="trade-rumor-entry"><h4>${esc(r.commodity)}</h4><p>Deal at <strong>${esc(stationLabel(r.dealPort||r.dealStation))}</strong></p><p class="trade-rumor-date">Heard ${date(r.day)} · day ${fmt(r.day)} · ${r.ageDays===0?'today':fmt(r.ageDays)+' days ago'}</p><p>Heard at ${esc(r.venue)} · ${esc(stationLabel(r.port||r.station))}</p><p class="small">${esc(r.speaker)} · ${r.source==='round'?'Over a round of drinks':r.source==='overheard'?'Overheard in conversation':'Canteen conversation'}</p><details><summary>Original report</summary><div class="trade-rumor-report">${rich(E.immersiveText(r.text))}</div></details></article>`;
 return `<section class="trade-rumor-journal" aria-label="Trade rumors"><h3>Trade rumors</h3>${rows.length?`<p class="small muted">Original reports from every port. Prices and stock may have changed since you heard them.</p>${rows.slice(0,12).map(card).join('')}${rows.length>12?`<details><summary>Earlier trade rumors (${rows.length-12})</summary>${rows.slice(12).map(card).join('')}</details>`:''}`:'<p class="muted">Cargo tips you hear in canteens will appear here.</p>'}</section>`;
}
function commissionJournalHTML(){const list=E.commissionJournal(state),bounties=E.bountyOffers(state).filter(r=>(r.accepted||r.captured)&&!r.completed);return (bounties.length?'<h3>Bounties</h3>'+bounties.map(r=>`<p><strong>${esc(r.title)}</strong> · ${r.captured?'Claim '+fmt(r.claimReward)+' cr at a patrol office':fmt(r.reward)+' cr after confirmed capture'}</p>`).join(''):'')+diplomaticJournalHTML()+civilianJournalHTML()+campaignJournalHTML()+raiderJournalHTML()+(list.length?`<h3>Personal commissions</h3>${list.map(q=>`<p><strong>${esc(q.host)} · ${esc(stationLabel(q.port||q.station))}</strong></p>${commissionCardHTML(q)}`).join('')}`:'');}
function establishmentDescription(v,p){
 const work={
 "market": "Cargo brokers match arriving shipments with the needs of local habitats and visiting crews. Consignment records, supply certificates and freight manifests move across the counter while handlers prepare sealed trade lots for transfer. The exchange deals in processed goods, linking this station’s everyday needs to the wider shipping network.",
 "contracts": "Dispatchers coordinate client-owned shipments between licensed destinations, pairing available hold space with delivery commitments. Each consignment has a named destination, a timetable and handling terms to review before acceptance. Incoming notices and delivery receipts trace the movement of goods between otherwise distant communities.",
 "shipyard": "Drive engineers and hull technicians keep visiting vessels ready for their next passage. Service crews work through propellant loading, integrity repairs and engineering stores, with specialist ammunition handled through the dock’s own supply catalogue. Maintenance here follows the condition of each hull and the equipment actually fitted aboard it.",
 "fleet": "The registry brings local ship offers, outfitting records and fleet administration together at the spaceport. Its staff reconcile hull ownership, fitting specifications and berth assignments as captains plan their next purchase or refit. Available vessels depend on local stock; the registry’s records also help crews coordinate ships already in their fleet.",
 "security": "Patrol staff issue capture warrants, register the bounties you accept and share the latest intelligence from surrounding routes. A report points to possible trouble during ordinary travel; the office’s work is to connect observations, verify outcomes and arrange the handover of captured raiders.",
 "relay": "Station coordinators arrange ship and fleet escort contracts, passenger charters, medical transfers and evacuation flotillas, alongside arrivals, departures and navigation reports. Route briefings, cargo manifests and delivery timetables share desk space with observations submitted by returning crews. The office helps captains prepare a departure around current access, crew readiness and the practical hazards of the surrounding corridors.",
 "clinic": "Medical coordinators oversee recovery berths, treatment schedules and the clinic’s reserve supplies. Visiting crews can review care, contribute eligible medical goods or discuss supervised research when work is available. The clinic balances the needs of transient crews with a resident community that depends on reliable shipments and carefully maintained equipment.",
 "local": "The commons gives station workers and visiting crews a place to eat, rest and exchange news between shifts. Conversations move from ordinary work to route rumours, personal histories and occasional introductions. Familiar faces share the room with travellers passing through; what reaches a captain’s table depends on who is present and willing to talk.",
 "bank": "The credit cooperative maintains this station’s deposit accounts and lending desk. Its manager reviews local terms, available borrowing and repayment records with visiting captains, while the wider financial record keeps track of obligations elsewhere. The counter is a meeting point between long shipping schedules and the everyday credit needs of the station.",
 "authority": "The Port Authority combines the local clearance desk with an interplanetary government liaison. Its officer connects residents and visiting crews with their governing council, explains the Compact and the Veyr and Ilyri treaty records, and identifies the authority responsible for cross-border questions. Access applications still follow the destinations, experience and vessel qualifications handled by this office; the archive tells how those shared obligations were negotiated.",
 "warehouse": "The warehouse provides permanent local storage for eligible owned cargo. Custodians reconcile bay ownership, delivery receipts and collection manifests so goods remain accounted for while a fleet is away. Stored merchandise stays at this station until collected; the facility keeps those local holdings distinct from cargo aboard travelling ships."
};
 const localContext={
 "earth": "Every meal has already paid for a ride through Earth’s gravity well.",
 "moon": "Polar workers send ice upward, but purification and propellant processing still consume power.",
 "earth-high": "Lifted hardware arrives in batches, and a delayed coil can hold up an entire conversion.",
 "mars": "Greenhouses trade produce for sensors, medicine and machinery they cannot easily manufacture.",
 "phobos": "Low gravity helps move a load; it does not make rotating machinery safe.",
 "deimos": "We import water under measured contracts rather than assuming every small moon has an ice mine.",
 "mercury": "Sunshades and cooling loops determine when exposed equipment can be serviced.",
 "venus": "Water and food arrive by freighter. The hostile surface is not a convenient supply depot.",
 "ceres": "Water-rich material still needs excavation, separation, power and reliable processing.",
 "jupiter": "Jupiter has no solid surface dock; every crate here came through an orbital supply chain.",
 "callisto": "Farther out is safer than Io; it is still not an unshielded holiday destination.",
 "ganymede": "A large icy moon still needs specialist extraction and protected life-support systems.",
 "europa": "An ocean beneath ice does not make an open water market; research samples are not cargo.",
 "io": "Radiation sets the work roster. Imported water is guarded as carefully as electronics.",
 "saturn": "Every transfer needs another burn and another inspection, even with the rings in view.",
 "titan": "Your freighter stays in orbit; local vehicles handle the difficult descent and return.",
 "enceladus": "Interesting ice chemistry is not permission to scoop free propellant.",
 "rhea": "Stored ice needs dependable seals, power and stock records before anyone can promise delivery.",
 "iapetus": "A distant berth can be useful, but it also means a longer wait for the right component.",
 "uranus": "The planet’s tilted system complicates route planning; a larger engine does not erase geometry.",
 "miranda": "Small shipments matter here: one failed pump can use the entire spare stock.",
 "ariel": "Trade works when cargo certificates and actual delivered mass agree.",
 "titania": "A larger warehouse still cannot promise a component that has not arrived.",
 "oberon": "Supplies are scheduled carefully; emergency replacement parts travel the same distance as anything else.",
 "neptune": "At this distance, navigation mistakes turn into long supply problems rather than quick detours.",
 "triton": "Triton’s retrograde orbit adds real maneuver cost; a short line on the map can still be an expensive flight."
};
 return [work[v.id]||v.business,localContext[p.id]].filter(Boolean).join(' ');
}
// Short spoken exchanges are view state: never resubmit a game action to hear the next part.
function exchangeContext(v){return {person:v.person,role:v.role,venue:v.contactID||v.name==='A quiet table'?null:v.id||'local',station:E.port(state.location).name,body:E.port(state.location).body,character:v.character||{}};}
function spokenResponseHTML(text,key){const html=rich(E.immersiveText(text));return `<div class="response-speech" data-response-speech data-response-key="${esc(key)}"><div class="response-layout" aria-hidden="true">${html}</div><div class="response-ink" aria-hidden="true">${html}</div><div class="sr-only">${html}</div></div>`;}
function exchangeReplies(entry){
 const menu=SpacetraderExchanges.replyPage(entry.normal,entry.replyPage);entry.replyPage=menu.page;
 const more=menu.next===null?'':btn(menu.name,'exchange-replies',`data-scope="${entry.scope}" data-page="${menu.next}"`);
 return `<div class="${entry.scope==='host'?'visit-questions':'talk-actions'}" role="group" aria-label="${entry.scope==='host'?'Conversation replies':entry.scope==='crew'?'Crew replies':'Traveller replies'}">${menu.choices.join('')}${more}</div>`;
}

function exchangeBody(entry){
 const d=entry.decision;
 const response=d?`${d.title?`<p class="conversation-offer-title">${esc(d.title)}</p>`:''}${spokenResponseHTML(d.text,'decision:'+d.text)}${d.terms?`<p class="conversation-offer-terms">${esc(d.terms)}</p>`:''}${d.progress?`<p class="conversation-offer-progress">${esc(d.progress)}</p>`:''}${d.reason?`<p class="conversation-offer-reason">${esc(d.reason)}</p>`:''}${d.details?`<details class="conversation-offer-details"><summary>${esc(d.detailsTitle||'Plan and requirements')}</summary>${d.details}</details>`:''}`:spokenResponseHTML(entry.cursor.raw,'reply:'+entry.source);
 return `<div class="${entry.scope==='host'?'host-dialogue':'conversation'}" role="region" aria-live="polite" aria-atomic="true" aria-label="${esc(entry.context.person)}’s response">${response}</div><div data-conversation-controls>${exchangeReplies(entry)}</div><div class="conversation-feedback"><p data-conversation-status role="status" aria-live="polite"></p>${btn('Reconnect','conversation-reconnect',`data-scope="${entry.scope}" hidden`)}</div>`;
}

function conversationContextKey(scope){return [actionEpoch,conversationVisit,state.location,scope,exchangeSessions.get(scope)?.identity||''].join('|');}
function syncConversationControls(){
 for(const box of document.querySelectorAll('.conversation-exchange')){const scope=box.dataset.exchange,key=conversationContextKey(scope),status=box.querySelector('[data-conversation-status]'),retry=box.querySelector('[data-action="conversation-reconnect"]'),pending=!!conversationPending;box.querySelector('[data-conversation-controls]')?.setAttribute('aria-busy',String(pending));
  for(const b of box.querySelectorAll('[data-action="venue-talk"],[data-action="secret-talk"],[data-action="secret-accept"],[data-action="crew-talk"]')){if(pending&&!b.disabled){b.dataset.conversationPendingDisabled='true';b.disabled=true;}else if(!pending&&b.dataset.conversationPendingDisabled){delete b.dataset.conversationPendingDisabled;b.disabled=false;}}
  if(status)status.textContent=pending?'Recording reply…':conversationFeedback.key===key?conversationFeedback.message:'';
  if(retry)retry.hidden=pending||conversationFeedback.key!==key||!conversationFeedback.reconnect;
 }
}
async function conversationAction(scope,type,args,after=()=>{}){
 if(conversationPending){syncConversationControls();return false;}
 const token={scope,key:conversationContextKey(scope)};let failure=null;conversationPending=token;conversationFeedback={key:token.key,message:'',reconnect:false};syncConversationControls();
 let done=false;try{done=await act(type,args,error=>{failure=error;});}catch(error){failure=error;}finally{if(conversationPending===token)conversationPending=null;}
 if(token.key===conversationContextKey(scope)){
  if(done)after();else{const reconnect=saveState.startsWith('Save failed')||!sharedSession&&!native;
   if(scope==='host'&&modalKind==='establishment')refreshVisitModal();else if(scope==='crew'&&modalKind==='crew-conversation')showCrewConversation(args.id);else if(scope==='secret'&&modalKind==='establishment')refreshVisitModal();
   conversationFeedback={key:token.key,message:reconnect?'Reply not confirmed. Reconnect to check recorded progress before choosing again.':/reply|branch|not available|departed|not currently aboard/i.test(failure?.message||'')?'Conversation updated. Choose from the current replies.':failure?.message||'That reply could not be completed. Choose a current reply.',reconnect};
  }
 }
 syncConversationControls();return done;
}
async function reconnectConversation(scope){const key=conversationContextKey(scope);if(sharedSession)await sharedPoll();else if(!native)await bootShared();if(key===conversationContextKey(scope)){conversationFeedback={key,message:saveState.startsWith('Save failed')?'Still unable to check recorded progress. Reconnect and try again.':'Recorded progress checked. Choose a current reply.',reconnect:saveState.startsWith('Save failed')};if(scope==='host'&&modalKind==='establishment')refreshVisitModal();syncConversationControls();}}

function objectiveText(value){
 const paragraphs=String(value??'').split(/\n+/).map(p=>SpacetraderExchanges.sentences(p).map(original=>{
  let text=original;
  if(/This is a personal introduction, not a waiver|An unaccepted offer closes|repeating (?:this|a) (?:topic|choice).*experience/i.test(text))return '';
  const consequence=/(?:missing|missed|failure|abandon|breach|theft|withdraw|false certif|falsif|losing|lost cargo|lost hull|destroyed|no payment|no cash fine)/i.test(text);
  if(consequence)text=text.replace(/(?:up to\s*)?[+−–-]?\d+(?:[,.]\d+)?\s+(?:(?:commerce|navigation|engineering|diplomacy)\s+)?(?:XP|experience)\b/gi,'experience').replace(/(?:up to\s*)?[+−–-]?\d+\s+(?:wider\s+|local\s+)?(?:reputation|trust|standing)\b/gi,'standing');
  if(!consequence&&(/\b(?:XP|reputation|rapport|traits?)\b/i.test(text)||/\d+\s+(?:experience|trust|standing)\b/i.test(text))&&!/\b(?:cr|credits?|paid|payment|transferred|fee|stipend)\b/i.test(text)&&/\b(?:earn|gain|grant|reward|penalt|cost|reduce|lose|lost|loss|no extra|no repeat|no reward|repeat|chance|bonus)\w*\b/i.test(text))return '';
  text=text.replace(/(?:[+−–-]?\d+(?:[,.]\d+)?\s*(?:[–-]\s*\d+)?\s+)(?:(?:commerce|navigation|engineering|diplomacy)\s+)?(?:XP|experience)\b/gi,'')
   .replace(/(?:[+−–-]?\d+(?:[,.]\d+)?\s+)(?:(?:public|wider|local|issuing.station)\s+)?(?:reputation|trust|standing)\b(?:\s+at both ports)?/gi,'')
   .replace(/\b(?:reputation|local trust|standing|caution|resolve|empathy)\s*[+−–-]\s*\d+\b/gi,'')
   .replace(/\b(?:plus|and)\s+(?=[,.;]|$)/gi,'').replace(/(?:\s*[·,;]\s*){2,}/g,' · ')
   .replace(/\(\s*[·,; ]*\)/g,'').replace(/\*\*\s*\*\*/g,'').replace(/\s+[·,;]\s*(?=[.!?]|$)/g,'').replace(/\s+([.,;:!?])/g,'$1').replace(/\s{2,}/g,' ').trim();
  if(!/[A-Za-z0-9]/.test(text)||/\bXP\b/i.test(text))return '';
  if(/^(?:Earn|Reward|Rewards|Gain|Paid|and|plus)\s*[:.]?$/i.test(text))return '';
  return text;
 }).filter(Boolean).join(' '));
 return paragraphs.filter(Boolean).join('\n\n');
}
function objectiveTerms(q){const when=q.deadline!=null?`Due ${date(q.deadline)}${q.remaining!=null?' · '+q.remaining+' days remaining':''}`:q.duration!=null?`${q.duration} days from acceptance`:'';return [q.reward!=null?`${fmt(q.reward)} cr`:null,when].filter(Boolean).join(' · ');}
function objectiveCost(q){return [q.good&&q.quantity?`${q.quantity} ${q.goodName||E.goods.find(g=>g.id===q.good)?.name||'cargo units'}`:null,q.spares?`${q.spares} engineering spares`:null,q.days!=null?`${q.days} work ${q.days===1?'day':'days'}`:null,q.fee?`${fmt(q.fee)} cr`:null,q.units?`${q.units} engineering spares`:null,q.medicine?`${q.medicine} medical units`:null].filter(Boolean).join(' · ');}

function exchangeHTML(scope,source,text,v,normal,decision=null,identity=''){let entry=exchangeSessions.get(scope);if(!entry||entry.source!==source){entry={scope,source,cursor:SpacetraderExchanges.create(objectiveText(E.immersiveText(text)),exchangeContext(v)),reveals:{}};exchangeSessions.set(scope,entry);}entry.context=exchangeContext(v);entry.identity=scope==='host'?state.location+':'+venueID+':'+contactID:identity;entry.normal=normal;entry.decision=decision;return `<div class="conversation-exchange" data-exchange="${scope}">${exchangeBody(entry)}</div>`;}

function mountConversationResponses(){conversationRevealer.stop();for(const box of $('modal').querySelectorAll('.conversation-exchange')){const entry=exchangeSessions.get(box.dataset.exchange),speech=box.querySelector('[data-response-speech]');if(entry&&speech){const key=speech.dataset.responseKey;conversationRevealer.mount(speech,entry.reveals[key]||(entry.reveals[key]={elapsed:0}));}}syncConversationControls();}

function advanceExchange(scope,page){const entry=exchangeSessions.get(scope),box=document.querySelector(`[data-exchange="${scope}"]`);if(!entry||!box||conversationPending)return;entry.replyPage=Number(page)||0;const controls=box.querySelector('[data-conversation-controls]');if(!controls)return;controls.innerHTML=exchangeReplies(entry);syncConversationControls();controls.querySelector('button:not(:disabled)')?.focus({preventScroll:true});}

function hostConversationDecision(d,v){
 const currentNode=d.conversation.at(-1)?.conversationChoice;
 if(d.topics.some(t=>t.id==='tree-case-evidence'))return {title:'What would you do?',text:d.conversation.at(-1)?.text||'Let’s think through an example together.'};
 if(v.id==='local'&&currentNode==='tree-reputation-rumor')return {title:'Word around the docks',text:d.conversation.at(-1).text};
 if(v.id==='authority'&&/^tree-blockade-/.test(currentNode||'')){const q=E.blockadeOverview(state).offers.find(q=>'tree-blockade-'+q.destination===currentNode);if(q)return {title:q.title,text:q.description,terms:`${fmt(q.reward)} cr on return after victory · No expiry`,reason:q.reason||`${q.tier===1?2:3} hostile ships · Threat ${q.tier} / 3 · Reference patrol: ${q.referenceShip}`};}
 if(v.id==='local'&&/^tree-relic-sale-/.test(currentNode||'')){const c=E.relicCollectorOverview(state),q=c.offers.find(q=>'tree-relic-sale-'+q.id===currentNode);if(q)return {title:q.name,text:c.host.name+' offers to buy this relic.',terms:`${fmt(q.price)} cr paid to available funds`,reason:'Ownership transfers immediately and any equipped benefit ends. No automatic repurchase or duplicate free reward.'};}
 if(/^tree-relic-(discovery|battle|authority)$/.test(currentNode||'')){const q=E.relicHuntOverview(state,v.id).offers.find(q=>'tree-relic-'+q.method===currentNode);if(q)return {title:q.name,text:q.description,terms:q.terms,reason:q.reason||'One free grant of this relic per voyage. Stowed until equipped.'};}
 if(/^tree-crew-(first|second|third|fourth|fifth|sixth)$/.test(currentNode||'')){const c=E.crewOverview(state).candidates.find(c=>c.index===(['first','second','third','fourth','fifth','sixth'].indexOf(currentNode.slice(10))));if(c)return {title:c.name+' · '+c.role,text:E.crewTier(c).name+' · '+crewProfile(c).specialty+'. '+crewBenefit(c).detail,detailsTitle:'About this recruit & benefits',details:crewProfileHTML(c,true),terms:`${fmt(c.fee)} cr signing fee · ${fmt(c.daily)} cr per day, including off duty · Visiting until ${date(c.visitUntil)}`,reason:'Wages continue during travel and stopped days. Travel wages appear in the flight estimate; unpaid stopped-day wages use the original charter account. Release at a station ends future wages; no signing fee refund.'};return {title:'Traveller departed',text:'That visitor is no longer available. Ask the host for current introductions.',terms:'',reason:''};}
 const leaseChoice=currentNode;
 if(v.id==='local'&&/^tree-storage-(ordinary|bonded|discreet)$/.test(leaseChoice||'')){
  const q=E.warehouseLeaseOverview(state).offers.find(q=>'tree-storage-'+q.route===leaseChoice);
  if(q)return {title:q.tenant+' · '+q.name,text:`The tenant needs ${q.units} units of ${E.allGoods.find(g=>g.id===q.good).name.toLowerCase()} kept in your warehouse. The lot stays client-owned and reserves ${(q.kg/1000).toFixed(1)} t until collection.`,terms:`${q.duration} days · ${fmt(q.reward)} cr rent to the local bank at collection`,reason:q.illegal?`Contraband: seizure forfeits rent, damages reputation and bills ${fmt(q.liability)} cr. ${q.pack==='thermal-sleeve'?'Thermal sleeves':'Spectral liners'} must be stored here; one is consumed per selected inspection. Concealment reduces detection without guaranteeing clearance.`:q.reason||'Declared legal goods. Tenant space cannot hold your own stores during the agreed term.'};
 }
 const bounty=v.id==='security'?E.localBounties(state).find(r=>'tree-'+r.id===d.conversation.at(-1)?.conversationChoice):null;
 const reply=d.conversation.at(-1);if(bounty&&!bounty.accepted&&d.topics.some(t=>t.id==='tree-bounty-accept'))return {title:bounty.title,text:`Capture ${bounty.title}. Patrol believes the target may be near ${stationLabel(bounty.suspectedPort)}; the latest update is from day ${bounty.observedDay}.`,terms:`${fmt(bounty.reward)} cr after confirmed capture`};
 if(reply?.service||reply?.conversationChoice&&!['tree-offer','tree-private-offer','tree-accept','tree-check-promise','tree-project-work','tree-patron-deal'].includes(reply.conversationChoice))return null;
 const topics=d.topics.map(t=>t.id),q=d.tree.commission,brief=text=>SpacetraderExchanges.sentences(objectiveText(text)).slice(0,2).join(' ');
 if(topics.includes('tree-patron-buy')){const lot=E.relationshipOpportunities(state,v.id,v.contactID||'').deal;if(!lot)return null;return {title:'Reserved supplies',text:`I have set aside ${lot.quantity} units of ${lot.name.toLowerCase()} for you. Would you like the lot?`,terms:`${fmt(lot.unitPrice)} cr each · ${fmt(lot.total)} cr total`,reason:lot.canBuy?'':'Bring enough available cash and free hold space for the full lot.'};}
 if(topics.some(t=>/^tree-project-(verify|care|shortcut|open|confidential|falsify|confirm)$/.test(t))){const work=E.personalProjectsHere(state,v.id,v.contactID||'')[0];if(work)return {title:work.step.task,text:`${work.title}. This stage is assigned here; choose how to proceed.`,terms:work.step.options.length?'Choose an approach; the full cost is shown on each button.':objectiveCost(work.step),reason:[work.step.canWork?'':objectiveText(work.step.reason),work.step.options.some(o=>o.id==='falsify')?'False certification ends the project without payment and withdraws personal trust.':''].filter(Boolean).join(' '),details:work.step.options.length?'':rich(brief(d.conversation.at(-1)?.text||''))};}
 if(!q||!(topics.includes('tree-accept')||q.status==='active'&&topics.includes('tree-complete')))return null;
 const text=q.project?`Could you ${q.project.steps[0].task.toLowerCase()}, then ${q.project.steps[1].task.toLowerCase()}? Report back to me at ${stationLabel(q.port)} when both are signed off.`:brief(q.description),reason=objectiveText(q.reason||''),progress=q.status==='active'?objectiveText(q.progress):'';
 return {title:q.title,text,terms:objectiveTerms(q),progress,reason:[reason&&reason!==progress?reason:'','Missing the deadline means no payment, damaged standing and lost experience; no cash fine.',q.project?'False certification ends the project without payment and withdraws personal recommendations.':''].filter(Boolean).join(' '),details:q.project?privateProjectStepsHTML(q):''};
}
function hostConversationReplies(d,v){
 const work=E.personalProjectsHere(state,v.id,v.contactID||'')[0];
 const preference=conversationOfferPreference?.visit===conversationVisit?conversationOfferPreference.kind:'',topics=visibleMissionTopics(d).filter(t=>!t.unchanged);
 if(!topics.some(t=>t.id.startsWith('tree-storage-')))topics.sort((a,b)=>{const rank=t=>['tree-check-promise','tree-project-work','tree-project-review'].includes(t.id)?0:['tree-work','tree-bank-rates','tree-patrol-blockades','tree-market','tree-government'].includes(t.id)?1:['tree-story','tree-reconnect','tree-relationship'].includes(t.id)?2:['tree-offer','tree-private-offer'].includes(t.id)?(preference?99:5):4;return rank(a)-rank(b);});

 return topics.map(t=>{const approach=work?.step.options.find(o=>t.id==='tree-project-'+o.id),cost=approach?objectiveCost(approach):'',name=t.name;return btn(esc(name)+(cost?`<small>${esc(cost)}</small>`:''),'venue-talk',`data-topic="${t.id}"`,t.disabled,['tree-accept','tree-patron-buy','tree-complete','tree-bounty-accept','tree-storage-accept','tree-storage-conceal','tree-relic-accept','tree-relic-sell','tree-crew-hire','tree-blockade-accept'].includes(t.id)?'primary':'');}).join('');
}
function travellerConversationDecision(c){if(!c.quest?.canAccept)return null;const q=c.quest;return {title:q.title,text:SpacetraderExchanges.sentences(objectiveText(q.description)).slice(0,2).join(' '),terms:`${fmt(q.reward)} cr + ${q.relicName} · No deadline`,reason:'Abandoning damages standing here and across the network; no cash fine. '+(q.kind==='delivery'?'You buy the goods. Inspections can seize restricted cargo; successful illicit delivery also damages wider standing.':'Return the recovered archive to the issuing canteen; a dead drop accepts it after the traveller leaves.')};}
function travellerConversationReplies(c){return c.quest?.canAccept?btn('Yes, I’ll take the job.','secret-accept',`data-key="${c.key}"`,false,'primary')+btn('Not right now.','secret-talk',`data-key="${c.key}" data-choice="later"`)+btn('No, I’ll pass.','secret-talk',`data-key="${c.key}" data-choice="decline"`):c.choices.map(o=>btn(esc(o.name),'secret-talk',`data-key="${c.key}" data-choice="${o.id}"`)).join('');}
function selectEstablishmentContact(id){exchangeSessions.clear();conversationOpening=true;conversationVisit++;contactID=id;refreshVisitModal();const people=$('modal').querySelector('.visit-people');if(people)people.scrollTop=0;$('establishment-contact')?.focus({preventScroll:true});}
document.addEventListener('change',e=>{if(e.target.id==='establishment-contact')selectEstablishmentContact(e.target.value);});
function establishmentHTML(){
 const d=E.establishmentVisit(state,venueID,contactID,conversationOpening),v=d.host,contacts=E.stationContacts(state.location,venueID,state);
 const reply=d.conversation.at(-1),exchange=exchangeHTML('host',conversationVisit+':'+(reply?.id||'greeting')+':'+(reply?.text||v.greeting),reply?.text||v.greeting,v,hostConversationReplies(d,v),hostConversationDecision(d,v));
 return `<header class="visit-header"><div><h2 id="modal-title">${esc(establishmentTitle(venueID))}</h2><p class="visit-location">${esc(stationLabel(state.location))}</p></div>${btn('Return to station','close')}</header><div class="establishment-layout"><section class="visit-people">${contacts.length>1?`<label class="contact-picker" for="establishment-contact"><span>Speak with</span><select id="establishment-contact" aria-label="Speak with">${contacts.map(c=>`<option value="${esc(c.contactID||'')}" ${(c.contactID||'')===contactID?'selected':''}>${esc(c.person)}</option>`).join('')}</select></label>`:''}<div class="host-profile">${portraitSVG(v,128)}<div><h2>${esc(v.person)}</h2><p>${esc(v.role)}</p></div></div>${v.contactID?`<p class="host-business">${esc(v.business)}</p>`:''}${exchange}</section><section class="station visit-services${venueID==='market'?' exchange-services':venueID==='contracts'?' freight-services':venueID==='fleet'?' registry-services':venueID==='shipyard'?' dock-services':venueID==='authority'?' authority-services':venueID==='warehouse'?' warehouse-services':''}"><div class="venue-service-features">${relicLeadsPanel(v.id)}${establishmentServices(v)}</div></section></div>`;
}
function showEstablishment(){openModal('establishment',establishmentHTML());syncAudioScene();$('modal').classList.add('establishment-dialog');positionMainModal();const log=$('modal').querySelector('.host-dialogue');log.scrollTop=0;if(venueID==='fleet')mountFleetPreviews();}
function utilityTitle(name){return {'At berth':'Fleet overview',Saves:'Progress',Log:'Journal',Captain:'Captain’s record'}[name]||name;}
function showUtility(name,fleetFilter){if(name==='Saves'){showLedger();return;}if(['Fleet overview','At berth'].includes(name))fleetRegisterFilter=fleetFilter??(name==='At berth'?'berthed':'active');tab=name;openModal('utility',modalHead(esc(utilityTitle(name)))+`<section class="station utility-content"${['Tasks','Captain','Log'].includes(name)?` tabindex="0" aria-label="${esc(utilityTitle(name))} contents"`:''}>${panel()}</section>`);$('modal').classList.add('utility-dialog');if(['Tasks','Captain','Log'].includes(name))$('modal').classList.add('records-dialog');if(['Fleet overview','At berth'].includes(name)){$('modal').classList.add('fleet-overview-dialog');mountFleetPreviews();}positionMainModal();if(['Saves','Log','Tasks','Captain'].includes(name))$('modal').scrollTop=0;if(name==='Log')mountJournalHistory();}
function refreshVisitModal(){
 if(modalKind==='financial'){
  if(screen==='battle'||state.incident){closeModal();return;}
  const scroll=$('modal').querySelector('.utility-content')?.scrollTop||0,focus=document.activeElement?.dataset?.section;
  showFinancial(financeSection,false);const pane=$('modal').querySelector('.utility-content');if(pane)pane.scrollTop=scroll;
  if(focus)[...$('modal').querySelectorAll('[data-section]')].find(b=>b.dataset.section===focus)?.focus({preventScroll:true});return;
 }
 if(!['establishment','utility','menu'].includes(modalKind))return;
 if((screen==='battle'||state.incident)&&!(modalKind==='utility'&&['Fleet overview','At berth'].includes(tab))){closeModal();return;}
 const kind=modalKind,old=$('modal'),active=document.activeElement,focusID=active?.id,focusData=active?.dataset?{...active.dataset}:null,bankAmounts=[...old.querySelectorAll('[data-bank-amount]')].map(input=>[input.id,input.value]);conversationRevealer.stop();
 const positions=[...old.querySelectorAll('.visit-people,.visit-services,.utility-content,.fleet-register-list,.fleet-register-detail,.registry-content,.registry-list,.dock-content')].map(el=>el.scrollTop);
 const fleetRegister=kind==='utility'&&['Fleet overview','At berth'].includes(tab)||kind==='establishment'&&venueID==='fleet';if(fleetRegister)stopFleetPreviews();
 old.innerHTML=kind==='menu'?gameMenuHTML():kind==='establishment'?establishmentHTML():modalHead(esc(utilityTitle(tab)))+`<section class="station utility-content"${['Tasks','Captain','Log'].includes(tab)?` tabindex="0" aria-label="${esc(utilityTitle(tab))} contents"`:''}>${panel()}</section>`;
 [...old.querySelectorAll('.visit-people,.visit-services,.utility-content,.fleet-register-list,.fleet-register-detail,.registry-content,.registry-list,.dock-content')].forEach((el,i)=>el.scrollTop=positions[i]||0);
 for(const [id,value] of bankAmounts){const input=$(id);if(input)input.value=value;}if(bankAmounts.length)syncBankAmountControls();
 const log=old.querySelector('.host-dialogue');if(log)log.scrollTop=0;
 mountConversationResponses();if(fleetRegister)mountFleetPreviews();
 let focus=focusID?document.getElementById(focusID):null;
 if(!focus&&focusData?.action)focus=[...old.querySelectorAll('button[data-action]')].find(el=>Object.keys(focusData).every(k=>el.dataset[k]===focusData[k]));
 (focus||old.querySelector('button'))?.focus({preventScroll:true});
}

let battleStage=null;
function combatSVG(scene,animate=true){
 const nodes=scene.units||[],fx=animate&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const ship=v=>{const model=E.shipVisual({shipID:v.shipID,hull:v.hull,upgrades:v.upgrades,ammo:0});return `<g data-combat-id="${esc(v.id)}" data-x="${v.x*760}" data-y="${v.y*550}" data-scale="${v.scale||1}" transform="translate(${v.x*760} ${v.y*550}) scale(${v.scale||1})"><g class="${fx&&scene.order==='burn'&&v.friendly&&v.selected?'combat-evade':fx?'combat-drift':''}" style="animation-delay:-${v.y*3}s">${scene.order==='live'&&fx&&v.hull>0?'<path class="live-engine-trail" d="M-45 0L-85 0" stroke="#89c4d0" stroke-width="3"/>':''}<g transform="translate(-65 -40) scale(.325)">${shipImage(model)}</g>${scene.order==='guard'&&v.friendly&&v.selected?'<circle r="47" stroke="#82b4cf" stroke-width="2" fill="#82b4cf11" class="combat-guard"/>':''}${scene.order==='repair'&&v.friendly&&v.selected?'<path d="M-7 0H7M0 -7V7" stroke="#82b4a5" stroke-width="4" class="combat-repair"/>':''}</g><text x="0" y="48" text-anchor="middle" fill="#e4e9e9">${esc(v.name)}</text><rect x="-36" y="57" width="72" height="3" fill="#69818e44"/><rect x="-36" y="57" width="${72*v.hull/v.maxHull}" height="3" fill="${v.friendly?'#d5ae68':'#bd6455'}"/></g>`;};
 const shots=fx?(scene.shots||[]).map(shot=>{const a=nodes.find(v=>v.id===shot.from),b=nodes.find(v=>v.id===shot.to);if(!a||!b)return '';return `<path class="${shot.weapon==='laser'?'combat-laser':shot.weapon==='ordnance'?'combat-shot live-missile':'combat-shot'}" d="M${a.x*760} ${a.y*550}L${b.x*760} ${b.y*550+(shot.hit?0:35)}" stroke="${shot.weapon==='laser'?'#89e3ee':shot.friendly?'#d5ae68':'#ecaa99'}" stroke-width="3" fill="none"/>${shot.hit?`<circle class="combat-impact ${shot.shield>0?'live-shield-hit':''}" cx="${b.x*760}" cy="${b.y*550}" r="25" fill="none" stroke="#e4e9e9" stroke-width="4"/>`:''}`;}).join(''):'';
 return `<svg class="combat-plot" viewBox="0 0 760 550" role="img" aria-label="Animated tactical ships and committed battle orders"><path d="M380 30V520M70 275H690" stroke="#69818e33" stroke-dasharray="4 12"/><circle cx="380" cy="275" r="190" fill="none" stroke="#69818e22"/>${nodes.map(ship).join('')}${shots}<text x="30" y="28" fill="#d5ae68">Your formation</text><text x="575" y="28" fill="#ecaa99">Hostile contacts</text><text x="30" y="532" fill="#a8bfcc">Tactical display · positions and time compressed</text></svg>`;
}
function renderBattleScreen(){
 const el=$('battle-content');if(!el)return;
 const retainedStage=battleStage?.element;
 const oldPositions=new Map([...el.querySelectorAll('[data-combat-id]')].map(n=>[n.dataset.combatId,{x:Number(n.dataset.x),y:Number(n.dataset.y),scale:Number(n.dataset.scale)}]));
 const recent=battleFX&&performance.now()-battleFX.at<2000,scene=recent?battleFX.scene:state.battle?E.combatScene(state,state):{units:[],shots:[],caption:'No active engagement.'};
 const report=state.battleHistory.at(-1);
 if(state.battle?.live&&battleStage?.battle===state.battle.id&&battleStage.element.isConnected&&el.querySelector('.live-command-panel')){refreshBattleControls();battleStage.update(scene,{selected:battleActor,target:battleTarget,running:liveRunning,step:state.battle.live.step});resumeRecordedBattle();return;}
 el.innerHTML=`<div class="combat-deck"><section class="combat-view"><h2>${state.battle?'Tactical command':report?'Engagement complete':'Combat readiness'}</h2>${state.battle?transitContextHTML():''}${scene.units.length?'<div id="battle-stage-slot"></div>':'<div class="combat-empty"><span>◇</span><p>No hostile contact</p><p>Visit a station’s patrol office for uncertain raider sightings. Encounters happen during normal travel.</p></div>'}<p class="combat-caption" role="status">${esc(state.battle?.rulesVersion===2&&(state.battle.live||!state.battle.acted.length)?(state.battle.live?.engaged?'Ships turn toward their targets automatically. Select a ship to change its live orders.':'Set standing orders before engaging. Weapon banks fire on their own reload cycles.'):scene.caption)}</p></section><section class="battle-controls${state.battle?.rulesVersion===2?' battle-controls-v2':''}${state.battle?.rulesVersion===2&&(state.battle.live||!state.battle.acted.length)?' live-command-panel':''}">${state.battle?battleMarkup():report?`<h2>${esc(report.title)}</h2><p>${esc(report.summary)}</p><p>${report.outcome} · ${report.rounds} rounds · ${fmt(report.reward)} cr</p>${btn('Review fleet','review-fleet','',false,'primary')}`:`<h2>Prepare your fleet</h2><p>Fit weapons, load ammunition and assign escorts at a station. Pirate encounters during normal travel can lead to battle.</p>${btn('Go to station','screen','data-screen="station"')}`}</section></div>`;placeBattleSelectors();syncBattleControlState();const slot=$('battle-stage-slot');if(slot&&scene.units.length){if(!battleStage||battleStage.battle!==state.battle?.id){battleStage?.dispose();battleStage=SpacetraderBattleStage.create({battle:state.battle?.id,model:u=>E.shipVisual({shipID:u.shipID,hull:u.hull,upgrades:u.upgrades,ammo:0}),bank:(u,slot)=>E.weaponFits(u).find(w=>w.slot===slot)});}slot.replaceWith(retainedStage===battleStage.element?retainedStage:battleStage.element);battleStage.update(scene,{selected:battleActor,target:battleTarget,running:liveRunning,step:state.battle?.live?.step||0});}resumeRecordedBattle();
}
function showAsteroidEncounter(){const q=E.fleetManeuverFuel(state,.12),ok=E.fleetOverview(state).fuel+1e-8>=q;openModal('encounter',modalHead('Belt corridor advisory',false)+rich(state.incident.detail)+encounterOption('Wait for corridor clearance','Adds four days, no damage or extra propellant. Reserve berth fees and interest continue.','belt-wait')+encounterOption('Plot a correction',`Adds two days. Every ship burns a 0.12 km/s correction; total ${q.toFixed(3)} t.`,'belt-detour',!ok)+encounterOption('Continue under shielding','Adds one day; flagship and every active escort lose 8 integrity.','belt-shield'));}

function compactHomeBasePanel(h,r){const rate=Math.round(Math.abs(r.serviceDiscount)*100);return `<section class="home-base home-base-compact" aria-labelledby="home-standing-title"><h3 id="home-standing-title">Home base & standing</h3><p class="home-address"><strong>${esc(h.station)}</strong><span>${esc(stationLabel(h.port,false))}${h.here?' · Registered here':''}</span></p><dl class="home-standing-scores"><div><dt>Public standing</dt><dd>${r.publicScore>0?'+':''}${r.publicScore}</dd></div><div><dt>Local standing</dt><dd>${r.score>0?'+':''}${r.score}</dd></div></dl><p class="home-service-rate">${rate?rate+'% service '+(r.serviceDiscount<0?'surcharge':'discount'):'Standard service rates'}</p><div class="home-compact-actions">${!h.here?btn('Register here · '+fmt(h.fee)+' cr','register-home','',!h.canMove,'primary'):''}${btn('Plot home base','home-route')}</div>${!h.here&&!h.canMove?`<p class="home-registration-reason">${esc(h.reason)}</p>`:''}</section>`;}
function homeBasePanel(registry=false){const h=E.homeBaseOverview(state),r=h.local;if(registry)return compactHomeBasePanel(h,r);return `<section class="light-note home-base"><h3>Home base & station standing</h3><p><strong>${esc(stationLabel(h.port))}</strong>${h.here?' · Your registered home port':''}</p><p class="small">${esc(h.benefits)}</p><div class="home-reputation"><p><small>Wider reputation</small><strong>${r.publicScore>0?'+':''}${r.publicScore} / 100</strong></p><p><small>${esc(stationLabel(r.port||r.station))}</small><strong>${r.score>0?'+':''}${r.score} / 100</strong></p></div><p>${esc(r.reception)}</p><p class="small">Service quotes here: ${Math.round(Math.abs(r.serviceDiscount)*100)}% ${r.serviceDiscount<0?'surcharge':'discount'}. Local actions are remembered here; your wider reputation follows you.</p>${registry&&!h.here?`<p class="small">${esc(h.reason||'Register while docked. 30 days between moves; ships, loans and reputation records stay in place.')}</p>${btn('Make this my home base · '+fmt(h.fee)+' cr','register-home','',!h.canMove,'primary')}`:''}${btn('Plot home base','home-route')}${registry?'':r.history.slice().reverse().map(e=>`<p class="small">Day ${e.day} · ${e.change>0?'+':''}${e.change} · ${esc(e.reason)}</p>`).join('')}</section>`;}
function stationReputationPanel(){return `<details class="light-note"><summary>Reputation at known stations</summary>${E.reputationRoster(state).map(r=>`<p><strong>${esc(stationLabel(r.port||r.station))}${r.home?' · Home':''}</strong> · ${r.score>0?'+':''}${r.score}<br><small>${esc(r.label)}</small></p>`).join('')}</details>`;}
function creditEnforcementGuide(){const d=E.debtCollectionOverview(state);return `<details class="light-note"><summary>Local credit enforcement</summary><p><strong>Owed here: ${financeMoney(d.localDebt)} / ${fmt(d.limit)} cr</strong></p><p class="small">${esc(d.policy)}</p>${d.reports.slice().reverse().map(r=>`<details><summary>Day ${r.day} · ${financeMoney(r.paid)} collected${r.items.length?' · assets seized':''}</summary><p>${esc(objectiveText(r.summary))}</p>${r.items.map(i=>`<p class="small">${i.quantity} × ${esc(i.name)} · ${fmt(i.value)} cr</p>`).join('')}</details>`).join('')}</details>`;}
function creditReviewHTML(b){
 const p=b.portfolio;return `<details class="service-details"><summary>Loan assessment</summary><dl class="service-metrics"><div><dt>Outstanding debt · all banks</dt><dd>${fmt(p.totalDebt)} cr</dd></div><div><dt>Hull liquidation estimate</dt><dd>${fmt(p.hullValue)} cr</dd></div><div><dt>Fittings liquidation estimate</dt><dd>${fmt(p.equipmentValue)} cr</dd></div><div><dt>Owned cargo · all ships</dt><dd>${fmt(p.aboardCargo)} cr</dd></div><div><dt>Goods in local & remote warehouses</dt><dd>${fmt(p.warehouseCargo)} cr</dd></div><div><dt>Cash & all deposits</dt><dd>${fmt(p.cash+p.deposits)} cr</dd></div><div><dt>Unborrowed cash & deposits</dt><dd>${fmt(p.unborrowedLiquidity)} cr</dd></div><div><dt>Asset-backed lending</dt><dd>${fmt(p.equitySupport)} cr</dd></div><div><dt>Shared lending ceiling</dt><dd>${fmt(p.networkLimit)} cr</dd></div><div><dt>Shared credit remaining</dt><dd>${fmt(p.networkHeadroom)} cr</dd></div><div><dt>This branch’s ceiling</dt><dd>${fmt(b.creditLimit)} cr</dd></div></dl><p class="small muted">Includes travelling and berthed ships at their actual locations. Estimates are reviewed before each new loan. Full lending rules are in the Guide.</p></details>`;
}
function steppedBankAmount(raw,delta){const n=Number(raw),value=Number.isSafeInteger(n)&&n>0?n:0,next=Math.max(0,Math.min(999999999,value+delta));return next?String(next):'';}
function bankManualLimits(b){return {deposit:b.maxDeposit,withdraw:b.maxWithdraw,borrow:b.maxBorrow,repay:Math.min(state.credits,state.debt)};}
function bankAmountInput(scope='deposits'){return $('bank-'+(scope==='credit'?'credit':'deposits')+'-amount');}
function syncBankAmountControls(){
 const modal=$('modal');if(!modal)return;const limits=bankManualLimits(E.bankOverview(state));
 modal.querySelectorAll('[data-bank-amount]').forEach(input=>{const box=input.closest('.bank-controls'),amount=Number(input.value),valid=input.value.trim()!==''&&Number.isSafeInteger(amount)&&amount>0&&amount<=999999999;
 box.querySelectorAll('[data-bank-manual]').forEach(button=>{button.disabled=!valid||amount>limits[button.dataset.bankManual];button.title=!valid?'Enter a positive whole-credit amount.':amount>limits[button.dataset.bankManual]?'Available limit: '+fmt(limits[button.dataset.bankManual])+' cr':button.dataset.kind==='borrow'?'Borrow at the displayed annual rate.':button.textContent.trim()+' '+fmt(amount)+' cr';});
 const minus=box.querySelector('[data-action="bank-amount-step"][data-delta="-1000"]'),plus=box.querySelector('[data-action="bank-amount-step"][data-delta="1000"]');if(minus)minus.disabled=!Number.isFinite(amount)||amount<=0;if(plus)plus.disabled=amount>=999999999;});
}
function stepBankAmount(delta,scope='deposits'){const input=bankAmountInput(scope);if(!input)return;input.value=steppedBankAmount(input.value,delta);syncBankAmountControls();input.focus({preventScroll:true});}
function bankActionArguments(button){const kind=button.dataset.kind,scope=button.dataset.bankScope||(['deposit','withdraw'].includes(kind)?'deposits':'credit');return {...(button.dataset.max==='true'?{max:true}:{amount:Number(bankAmountInput(scope).value)}),...(kind==='borrow'?{rateMode:button.dataset.rateMode==='fixed'?'fixed':'floating'}:{})};}
function bankControlsHTML(b,scope='deposits'){
 const credit=scope==='credit',id='bank-'+scope+'-amount',label=credit?'Credit amount in credits':'Deposit amount in credits',actions=credit?[['repay','Repay loans',b.maxRepayLocal]]:[['deposit','Debit',b.maxDeposit],['withdraw','Credit',b.maxWithdraw]],tag=`data-bank-scope="${scope}"`;
 const loans=credit?`<div class="bank-operation bank-loan-actions" role="group" aria-label="Borrow at an annual rate">${[['floating',b.loanAPR],['fixed',b.fixedAPR]].map(([mode,rate])=>btn('Borrow '+mode+' · '+(rate*100).toFixed(2)+'% / yr','bank-action',`${tag} data-bank-manual="borrow" data-kind="borrow" data-rate-mode="${mode}" title="Borrow the entered credit amount at ${(rate*100).toFixed(2)}% per year"`,true,'bank-manual')).join('')}</div>`:'';
 return `<div class="bank-controls" role="group" aria-label="${credit?'Credit':'Deposit'} transactions"><div class="bank-amount-heading"><label for="${id}">Amount in credits</label>${credit?btn('Use maximum credit · '+fmt(b.maxBorrow)+' cr','bank-borrow-max','',b.maxBorrow<1,'bank-credit-fill'):''}</div><div class="bank-amount-stepper">${btn('−1,000','bank-amount-step',`${tag} data-delta="-1000" aria-label="Subtract 1,000 from ${credit?'credit':'deposit'} amount"`,true)}<input id="${id}" data-bank-amount data-bank-scope="${scope}" type="number" inputmode="numeric" min="0" max="999999999" step="1" value="" placeholder="Enter amount" autocomplete="off" aria-label="${label}">${btn('+1,000','bank-amount-step',`${tag} data-delta="1000" aria-label="Add 1,000 to ${credit?'credit':'deposit'} amount"`)}</div><div class="bank-operation-list">${loans}${actions.map(([kind,title,max])=>`<div class="bank-operation" role="group" aria-label="${title}">${btn(title,'bank-action',`${tag} data-bank-manual="${kind}" data-kind="${kind}" title="Enter an amount within the available limit"`,true,'bank-manual')}${btn((kind==='repay'?'Repay here':'Max')+' · '+fmt(max)+' cr','bank-action',`${tag} data-kind="${kind==='repay'?'repay-local':kind}" data-max="true" aria-label="${kind==='repay'?'Repay this bank':title} maximum ${max} credits"`,max<1,'bank-maximum')}</div>`).join('')}</div></div>`;
}
function bankPanel(){
 const b=E.bankOverview(state),pct=n=>(n*100).toFixed(2)+'%',local=b.loans.filter(l=>l.port===state.location&&l.balance>0),rates=[];
 const fixed=local.filter(l=>l.rateMode!=='floating').length,floating=local.some(l=>l.rateMode==='floating');
 if(fixed)rates.push(fixed+' fixed '+(fixed===1?'agreement':'agreements'));if(floating)rates.push('Floating credit');if(state.location==='earth'&&b.legacyDebt>0)rates.push('Charter · fixed 4.00%');
 return `<div class="bank-sections"><section class="bank-section bank-deposits" aria-labelledby="bank-deposits-title"><header class="bank-section-heading"><h3 id="bank-deposits-title">Deposit</h3><div><strong>${financeMoney(b.localDeposit)}</strong><small>Earns ${pct(b.depositAPR)} / year</small></div></header>${bankControlsHTML(b,'deposits')}</section><section class="bank-section bank-credit" aria-labelledby="bank-credit-title"><header class="bank-section-heading"><h3 id="bank-credit-title">Loan</h3></header><div class="bank-summary" aria-label="Local credit balances"><div><span>Borrowed here</span>${btn(financeMoney(b.localDebt),'finances','data-section="Loans" aria-label="View loan details"',false,'bank-account-link')}<small>${esc(rates.join(' · ')||'No local loans')}</small></div><div><span>Available credit</span><strong>${fmt(b.maxBorrow)} cr</strong><small>${fmt(b.approvedCreditLimit)} cr total allowance</small></div></div>${bankControlsHTML(b,'credit')}</section></div>`;
}

// Update the scoped quote in place: typing never replaces the focused field or button.
document.addEventListener('input',e=>{if(e.target.id==='dock-tonnes')syncDockFuelControls();});

function financeMoney(n){return n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+' cr';}
function financeRow(label,value){return `<div class="finance-row"><span>${esc(label)}</span><strong>${financeMoney(value)}</strong></div>`;}
function financeAccount(a,deposit){
 const charter=a.id==='charter',place=charter?E.bankTerms('earth').name+' · '+stationLabel('earth',false):stationLabel(a.port||a.id||a.body,false),local=charter?state.location==='earth':a.local;
 return `<article class="account-record"><div><h3>${esc(a.name)}</h3><p>${esc(place)}${local?' · Here':''}</p></div><div class="account-record-amount"><strong>${financeMoney(a.balance)}</strong><span>${(a.apr*100).toFixed(2)}% / year · ${deposit||a.rateMode==='floating'?'Floating':'Fixed'}${a.fixedPremium?' · +'+(a.fixedPremium*100).toFixed(2)+' pp at signing':''}</span></div></article>`;
}
function financeVessel(v){return `<details class="finance-account"><summary>${esc(v.name)}${v.flagship?' · Flagship':''} · ${esc(stationLabel(v.port||v.station,false))} · <strong>${financeMoney(v.total)}</strong></summary><p>${esc(v.ship)} · integrity ${v.hull}% · ${esc(stationLabel(v.port||v.station))}</p>${financeRow('Hull estimate',v.hullValue)}${financeRow('Equipment',v.equipmentValue)}${financeRow('Cargo',v.cargoValue)}${v.equipment.map(u=>financeRow(u.name+' · level '+u.level,u.value)).join('')}${v.cargo.map(g=>financeRow(g.name+' · '+g.units+' units',g.value)).join('')}${!v.cargo.length?'<p class="muted">No cargo aboard.</p>':''}</details>`;}
function warehouseRegister(rows){
 const capacity=rows.reduce((n,w)=>n+w.capacityKg,0),free=w=>Math.max(0,w.capacityKg-w.usedKg),freeTotal=rows.reduce((n,w)=>n+free(w),0);
 return `<div class="account-total"><span>${rows.length} ${rows.length===1?'warehouse':'warehouses'} · ${(capacity/1000).toFixed(1)} t owned</span><strong>${(freeTotal/1000).toFixed(1)} t free</strong></div>${rows.length?rows.map(w=>`<article class="account-record"><div><h3>${esc(w.station)}</h3><p>${esc(stationLabel(w.id||w.station,false))}</p><small>${((w.usedKg-(w.leasedKg||0))/1000).toFixed(2)} t own stores · ${((w.leasedKg||0)/1000).toFixed(2)} t leased · ${(free(w)/1000).toFixed(2)} t free<br>${dec(w.volumeM3)} / ${dec(w.capacityM3)} m³ used<br>${w.blocks} ${w.blocks===1?'bay':'bays'} · storage & owned goods ${financeMoney(w.total)}</small>${w.leases?.length?`<p>${w.leases.map(j=>esc(j.tenant)+' · '+(j.status==='due'?'Rent pending':(j.units*.25).toFixed(1)+' t · '+date(j.endsDay))).join('<br>')}</p>`:''}</div><div class="account-record-amount"><strong>${(w.capacityKg/1000).toFixed(1)} t</strong>${w.id===state.location?btn('Open warehouse','venue','data-id="warehouse"'):btn('Plot '+esc(w.station),'plot',`data-id="${esc(w.id)}"`,!E.accessiblePorts(state).includes(w.id))}</div></article>`).join(''):'<p class="records-empty">No warehouses owned. Purchase storage at a station warehouse.</p>'}`;
}

function showFinancial(section='Deposits',remember=true){
 if(section==='Overview'){showUtility('Captain');return;}if(remember)financeReturn=modalKind==='establishment';const f=E.financialOverview(state),tabs=['Deposits','Loans','Fleet & cargo','Warehouses'];if(!tabs.includes(section))section='Deposits';financeSection=section;
 const content=section==='Deposits'?`<div class="account-total"><span>Total bank deposits · ${f.depositCount} ${f.depositCount===1?'account':'accounts'}</span><strong>${financeMoney(f.totalDeposits)}</strong></div>${f.deposits.length?f.deposits.map(a=>financeAccount(a,true)).join(''):'<p class="records-empty">No bank deposits yet.</p>'}`:
 section==='Loans'?`<div class="account-total"><span>Total loans · ${f.loanCount} ${f.loanCount===1?'balance':'balances'}</span><strong>${financeMoney(f.totalDebt)}</strong></div>${f.loans.length?f.loans.map(a=>financeAccount(a,false)).join(''):'<p class="records-empty">All loans repaid.</p>'}`:
 section==='Warehouses'?warehouseRegister(f.warehouses):`<div class="account-total"><span>${f.vessels.length} ${f.vessels.length===1?'ship':'ships'} · hulls, fittings & cargo</span><strong>${financeMoney(f.hullValue+f.equipmentValue+f.cargoValue)}</strong></div>${f.vessels.map(v=>`<article class="account-record"><div><h3>${esc(v.name)}${v.flagship?' · Flagship':''}</h3><p>${esc(v.ship)} · ${esc(stationLabel(v.port||v.station))}</p><small>Hull & fittings ${financeMoney(v.hullValue+v.equipmentValue)} · cargo ${financeMoney(v.cargoValue)}</small></div><div class="account-record-amount"><strong>${financeMoney(v.total)}</strong></div></article>`).join('')}`;
 const returnToDesk=financeReturn,head=returnToDesk?`<div class="dialog-head"><h2 id="modal-title">${esc(section)}</h2><div class="dialog-head-actions">${btn('Back to '+establishmentTitle(venueID),'finance-back')}${btn('Close','close')}</div></div>`:modalHead(esc(section));openModal('financial',head+`<section class="station utility-content financial-content" tabindex="0" aria-label="${esc(section)} contents"><nav class="finance-tabs" aria-label="Account pages">${btn('Captain’s record','tab','data-tab="Captain"')}${tabs.map(t=>btn(esc(t),'finance-section',`data-section="${esc(t)}" aria-pressed="${section===t}"`)).join('')}</nav>${content}</section>`);$('modal').classList.add('utility-dialog','records-dialog');financeReturn=returnToDesk;
}

let warehouseLot=1,warehouseMode='store',warehouseSelected='';
function warehouseView(){
 const w=E.warehouseOverview(state,'active');
 const storing=warehouseMode==='store',rows=w.rows.filter(r=>storing?r.aboard>0:r.stored>0).sort((a,b)=>{const rank=r=>r.kind==='cargo'?0:['supply','ammunition','legacy-ammunition'].includes(r.kind)?1:2;return rank(a)-rank(b)||(a.kind==='cargo'?marketBuyLow(a.id)-marketBuyLow(b.id):0)||a.name.localeCompare(b.name);});
 const selected=rows.find(r=>r.id===warehouseSelected)||rows[0];if(selected)warehouseSelected=selected.id;return {w,rows,selected,storing};
}
function warehouseDestination(storing=warehouseMode==='store'){return storing?'warehouse':'fleet';}
function warehouseUnavailable(r,storing){
 if((storing?r.maxStore:r.maxTake)>0)return '';
 return storing?'Unavailable · Not enough warehouse space':'Unavailable · No compatible space aboard';
}
function warehouseProductHTML(r){
 const selected=r.id===warehouseSelected,g=E.allGoods.find(g=>g.id===r.id)||{id:r.id},reason=warehouseUnavailable(r,warehouseMode==='store');
 return `<tr class="market-product${selected?' selected':''}"><th scope="row">${btn(commodityMark(g)+`<span>${esc(r.name)}${reason?`<small class="warehouse-unavailable">${esc(reason)}</small>`:''}</span>`,'warehouse-select',`data-id="${r.id}" aria-label="Select ${esc(r.name)}${reason?' · '+esc(reason):''}" aria-pressed="${selected}"`,false,'market-item-button')}</th><td class="market-ledger-owned">${fmt(r.aboard)}</td><td class="market-ledger-owned">${fmt(r.stored)}</td></tr>`;
}
function warehouseTransferMass(kg){return kg<1000?fmt(kg)+' kg':(kg/1000).toFixed(2)+' t';}
function warehouseOrderHTML(model){
 const {w,selected:r,storing}=model;if(!r)return model.rows.length?'<p class="exchange-order-empty" role="status">Select another item to prepare a transfer.</p>':'';
 const maximum=storing?r.maxStore:r.maxTake,n=warehouseLot,destination=warehouseDestination(storing),verb='Transfer to '+destination;
 return `<section class="exchange-order warehouse-order" data-warehouse-item="${r.id}" aria-label="Transfer ${esc(r.name)}"><div class="exchange-order-caption"><strong>${esc(r.name)}</strong><span>${maximum?fmt(maximum)+' available':'No units available'}</span></div><div class="exchange-order-controls"><div class="market-stepper" role="group" aria-label="${esc(r.name)} quantity controls">${btn('−','warehouse-step','data-delta="-1" aria-label="Decrease transfer quantity"',n<=1)}<input type="number" inputmode="numeric" min="1" max="1000" step="1" value="${n}" data-warehouse-quantity aria-label="Transfer quantity">${btn('+','warehouse-step','data-delta="1" aria-label="Increase transfer quantity"',n>=maximum)}</div>${btn('Max','warehouse-max',`data-maximum="${maximum}" aria-label="Set maximum ${maximum} ${esc(r.name)}"`,maximum<1,'exchange-max')}<div class="exchange-total" role="status" aria-live="polite"><small>Transfer</small><strong>${warehouseTransferMass(n*r.kg)}</strong></div>${btn(verb,'warehouse-transfer',`data-port="${w.port}" data-ship="active" data-item="${r.id}" data-units="${n}" data-store="${storing?1:0}" aria-label="Transfer ${n} ${esc(r.name)} to ${destination}"`,n>maximum,'primary exchange-confirm')}</div><p class="exchange-order-reason" aria-live="polite">${esc(warehouseUnavailable(r,storing))|| (n>maximum?'Choose up to '+fmt(maximum)+' for this transfer.':'')}</p></section>`;
}
function warehouseTenantList(leases,port=state.location){return leases.length?`<section class="warehouse-tenant-list" aria-label="Tenant leases">${leases.map(j=>`<article><div><strong>${esc(j.tenant)} · ${j.status==='due'?'Rent pending':(j.units*.25).toFixed(1)+' t'}</strong><small>${esc(E.allGoods.find(g=>g.id===j.good)?.name||j.good)} · ${j.status==='due'?'Rent pending · bank deposit limit reached':'Until '+date(j.endsDay)+' · '+fmt(j.reward)+' cr'}${j.illegal&&j.status==='active'?' · Restricted · '+esc(j.packing)+(j.packReady?' '+(j.packCount===1?'package':'packages'):''):''}</small></div>${j.canPack&&(!j.cover||!j.packReady)?btn('Use '+esc(j.pack==='thermal-sleeve'?'thermal sleeves':'spectral liners'),'warehouse-lease-pack',`data-port="${esc(port)}" data-id="${esc(j.id)}"`):''}</article>`).join('')}</section>`:'';}
function warehousePanel(){
 const model=warehouseView(),{w,rows,storing}=model;
 const empty=storing?'No owned items aboard the travelling fleet to transfer.':'No items stored in this warehouse.';
 return `<section class="warehouse-console"><div class="warehouse-summary"><div><strong>${(w.freeKg/1000).toFixed(2)} t free</strong><small>${(w.usedKg/1000).toFixed(2)} / ${(w.capacityKg/1000).toFixed(2)} t · ${dec(w.volumeM3)} / ${dec(w.capacityM3)} m³ · ${esc(w.tierLabel)}</small>${w.leasedKg?`<small>${((w.usedKg-w.leasedKg)/1000).toFixed(2)} t own stores · ${(w.leasedKg/1000).toFixed(2)} t leased</small>`:''}${w.capacityKg?`<progress max="${w.capacityKg}" value="${w.usedKg}" aria-label="Warehouse capacity used"></progress>`:''}${w.nextTier?`<small class="warehouse-next-tier">Next: ${esc(w.nextTier.label)} · ${fmt(w.nextTier.capacityKg/1000)} t · ${fmt(w.nextTier.capacityM3)} m³</small>`:''}</div>${btn(w.nextTier?(w.blocks?'Upgrade':'Buy storage')+' · '+fmt(w.price)+' cr':'Fully upgraded','warehouse-purchase',`data-port="${w.port}"`,!w.canBuy,'warehouse-buy-bay')}</div>${!w.blocks&&w.reason?`<p class="exchange-order-reason">${esc(w.reason)}</p>`:''}${w.blocks?`${warehouseTenantList(w.leases||[])}<div class="exchange-toolbar warehouse-toolbar"><div class="exchange-mode" role="group" aria-label="Transfer direction">${btn('Transfer to warehouse','warehouse-mode','data-mode="store" aria-pressed="'+storing+'"',false,storing?'selected':'')}${btn('Transfer to '+warehouseDestination(false),'warehouse-mode','data-mode="collect" aria-pressed="'+!storing+'"',false,!storing?'selected':'')}</div></div><div class="exchange-list warehouse-list" tabindex="0" role="region" aria-label="Warehouse inventory"><table class="market-ledger warehouse-ledger"><caption class="sr-only">Select an item to ${storing?'transfer to the warehouse':'transfer to the travelling fleet'}.</caption><colgroup><col class="warehouse-item-col"><col class="warehouse-count-col"><col class="warehouse-count-col"></colgroup><thead><tr><th scope="col">Item</th><th scope="col">Aboard</th><th scope="col">Stored</th></tr></thead><tbody>${rows.map(warehouseProductHTML).join('')}</tbody></table>${!rows.length?`<p class="warehouse-empty" role="status">${empty}</p>`:''}</div>${warehouseOrderHTML(model)}`:''}</section>`;
}
function refreshWarehouseConsole(focusID=''){
 const box=document.querySelector('.warehouse-console');if(!box)return;const scroll=box.querySelector('.warehouse-list')?.scrollTop||0;box.outerHTML=warehousePanel();const next=document.querySelector('.warehouse-console');if(next.querySelector('.warehouse-list'))next.querySelector('.warehouse-list').scrollTop=scroll;if(focusID)next.querySelector(`[data-action="warehouse-select"][data-id="${focusID}"]`)?.focus({preventScroll:true});
}
function updateWarehouseQuantity(input){
 const {selected:r,storing}=warehouseView();if(!r)return;const n=Number(input.value),valid=Number.isInteger(n)&&n>=1&&n<=1000,maximum=storing?r.maxStore:r.maxTake,box=input.closest('.warehouse-order'),destination=warehouseDestination(storing),verb='Transfer to '+destination,b=box.querySelector('[data-action="warehouse-transfer"]');
 if(valid)warehouseLot=n;input.setAttribute('aria-invalid',String(!valid));b.disabled=!valid||n>maximum;b.dataset.units=String(n);b.textContent=verb;b.setAttribute('aria-label',valid?`Transfer ${n} ${r.name} to ${destination}`:'Enter a whole number from 1 to 1,000');box.querySelector('.exchange-total strong').textContent=valid?warehouseTransferMass(n*r.kg):'—';box.querySelector('[data-delta="-1"]').disabled=!valid||n<=1;box.querySelector('[data-delta="1"]').disabled=!valid||n>=maximum;box.querySelector('.exchange-order-reason').textContent=!valid?'Enter a whole number from 1 to 1,000.':warehouseUnavailable(r,storing)|| (n>maximum?'Choose up to '+fmt(maximum)+' for this transfer.':'');
}
document.addEventListener('input',e=>{if(e.target.matches('[data-warehouse-quantity]'))updateWarehouseQuantity(e.target);});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-warehouse-quantity]'))e.target.select();});
document.addEventListener('keydown',e=>{const item=e.target.closest?.('[data-action="warehouse-select"]');if(!item||!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;const rows=[...item.closest('.warehouse-list').querySelectorAll('[data-action="warehouse-select"]')],i=rows.indexOf(item),next=e.key==='Home'?0:e.key==='End'?rows.length-1:Math.max(0,Math.min(rows.length-1,i+(e.key==='ArrowDown'?1:-1)));e.preventDefault();warehouseSelected=rows[next].dataset.id;warehouseLot=1;refreshWarehouseConsole(warehouseSelected);document.querySelector(`.warehouse-list [data-id="${warehouseSelected}"]`)?.scrollIntoView({block:'nearest'});});

function relicCabinetPanel(){
 const r=E.relicOverview(state),blocked=!!state.incident||!!state.battle;
 if(!r.owned.length&&!r.artifacts.length)return '';
 const rows=r.owned.map(v=>`<tr><th scope="row">${esc(v.name)}<small>${financeMoney(v.value)}</small></th><td>${esc(v.detail)}</td><td>${btn(v.equipped?'Stow':'Equip','relic-toggle',`data-id="${v.id}"`,blocked||!v.equipped&&r.equipped>=r.slots)}</td></tr>`).join('');
 const artifacts=(r.artifacts||[]).map(a=>`<tr><th scope="row">Recovered antiquity<small>${esc(a.shipName)} · ${esc(stationLabel(a.port))}</small></th><td>${esc(a.detail)}</td><td>${a.equipped?'Equipped':a.appraised?'Stowed':'Unappraised'}</td></tr>`).join('');
 return `<section class="captain-record-section relic-collection"><h3>Relics <span class="record-heading-meta">${r.equipped} / ${r.slots} active</span></h3><p class="record-note">New relics equip automatically when a slot is free. Appraise recovered cases first. Matching benefits use the strongest source.</p><table class="relic-table"><thead><tr><th scope="col">Relic</th><th scope="col">Benefit</th><th scope="col">Status</th></tr></thead><tbody>${rows}${artifacts}</tbody></table></section>`;
}
// A stable personal history is presentation, not a new saved agreement or an RNG draw.
function crewProfile(m){return E.crewCharacter(m);}

function crewBenefit(m){return E.crewBenefit(m);}
function crewBenefitStatus(m,candidate=false){
 const c=E.crewOverview(state),other=c.members.some(v=>v.id!==m.id&&v.onDuty&&v.skill===m.skill);
 if(state.fleetLoss)return 'Duty benefits are unavailable without a travelling fleet.';
 if(candidate&&(other||c.members.filter(v=>v.onDuty).length>=c.dutySlots))return 'Would join off duty. Assign a free duty position to activate this benefit.';
 if(!candidate&&!m.onDuty)return 'Off duty; benefit inactive. Wages continue.';
 const rank=E.crewTier(m).rank,relics=E.relicOverview(state),base=E.skillProgressForXP(state.profile.xp[m.skill]).level,a=E.crewSpecialties().find(a=>a.id===m.specialty);
 if(a){if((state.cantina?.equipped||[]).some(id=>{const r=E.relicCatalog().find(r=>r.id===id);return r?.effect===a.effect&&r.power>=a.step*rank;}))return 'This benefit is already covered by an equipped relic; matching benefits do not stack.';}
 else{if(m.skill!=='commerce'&&base>=10)return 'This skill is already fully trained; the skill benefit cannot increase it further.';if((relics.bonuses[m.skill]||0)>=rank)return 'This benefit is already covered by an equipped relic; matching benefits do not stack.';}
 return (candidate?'Applies while on duty.':'On duty.')+' Matching benefits use the strongest source.';
}

function crewProfileHTML(m,candidate=false){const p=crewProfile(m),b=crewBenefit(m);return `<div class="crew-profile"><p class="crew-specialty">${esc(E.crewTier(m).name)} · ${esc(p.specialty)} · ${esc(p.species)}</p><p class="crew-pay"><strong>${fmt(m.daily)} cr per ship-day</strong> · ${fmt(m.daily*30)} cr over 30 days, including off duty${m.termsVersion?'':' · Existing agreement'}</p><div class="crew-benefit"><h3>${esc(b.short)}</h3><p>${esc(b.detail)}</p><p class="crew-benefit-status">${esc(crewBenefitStatus(m,candidate))}</p></div><section><h3>Background</h3><p>${esc(p.history)}</p></section><section><h3>Why travel?</h3><p>${esc(p.goal)}</p></section><section><h3>Working style</h3><p>${esc(p.style)}</p></section><p class="record-note">${candidate?'Visiting until '+date(m.visitUntil):'Joined on '+date(m.hiredDay)} · ${esc(stationLabel(m.port))}</p></div>`;}
function showCrewProfile(id){const m=E.crewOverview(state).members.find(v=>v.id===id);if(!m)return;openModal('crew-profile',modalHead(esc(m.name))+`<section class="station utility-content crew-dossier" tabindex="0" aria-label="Crew member details"><p class="crew-role">${esc(m.role)} · ${m.onDuty?'On duty':'Off duty'}</p>${crewProfileHTML(m)}<p class="record-note">Matching crew and relic benefits use the strongest source. Earned qualifications stay unchanged.</p><div class="actions">${btn('Talk with '+esc(m.name),'crew-conversation',`data-id="${esc(m.id)}"`,!!state.incident||!!state.battle)}${btn('Back to Captain’s record','tab','data-tab="Captain"')}</div></section>`);$('modal').classList.add('utility-dialog','records-dialog');}
function showCrewConversation(id){const c=E.crewConversation(state,id),m=c.member,normal=c.choices.map(o=>btn(esc(o.name),'crew-talk',`data-id="${esc(id)}" data-choice="${esc(o.id)}"`,!!o.disabled||!!state.incident||!!state.battle)).join('');openModal('crew-conversation',modalHead(esc(m.name))+`<section class="station utility-content crew-dossier" tabindex="0" aria-label="Crew conversation"><p class="crew-role">${esc(m.role)} · ${m.onDuty?'On duty':'Off duty'}</p>${exchangeHTML('crew',id+':'+c.text,c.text,{person:m.name,role:m.role,name:m.role},normal,null,id)}<div class="actions">${btn('Back to crew details','crew-profile',`data-id="${esc(id)}"`)}${btn('Captain’s record','tab','data-tab="Captain"')}</div></section>`);$('modal').classList.add('utility-dialog','records-dialog');mountConversationResponses();}
function namedCrewPanel(){const c=E.crewOverview(state);return `<section class="captain-record-section named-crew"><h3>Named crew ${c.members.length?`<span class="record-heading-meta">${c.members.length} / ${c.slots} aboard</span>`:''}</h3>${c.members.length?`<p class="record-note">${fmt(c.daily)} cr per day · ${c.members.filter(m=>m.onDuty).length} / ${c.dutySlots} on duty</p>`:''}${c.members.length?`<table class="crew-table"><thead><tr><th scope="col">Crew member</th><th scope="col">Duty & benefit</th><th scope="col">Daily wage</th><th scope="col">Actions</th></tr></thead><tbody>${c.members.map(m=>`<tr><th scope="row">${btn(esc(m.name),'crew-profile',`data-id="${esc(m.id)}" aria-label="Details about ${esc(m.name)}"`,false,'crew-name')}<small>${esc(E.crewTier(m).name)} · ${esc(m.role)}</small></th><td>${esc(crewBenefit(m).short)}<small>${esc(crewBenefit(m).detail)}</small><small>${m.onDuty?'On duty':'Off duty'}</small></td><td>${fmt(m.daily)} cr</td><td><div class="crew-actions">${btn(m.onDuty?'Stand down':'Assign duty','crew-duty',`data-id="${esc(m.id)}"`,!!state.incident||!!state.battle||!m.onDuty&&(c.members.filter(m=>m.onDuty).length>=c.dutySlots||c.members.some(v=>v.onDuty&&v.skill===m.skill)))}${btn('Release…','crew-release-prompt',`data-id="${esc(m.id)}"`,!!state.incident||!!state.battle)}</div></td></tr>`).join('')}</tbody></table>`:'<p class="record-note">Ask a canteen or commons host about travelling specialists.</p>'}</section>`;}
function relicLeadsPanel(venue){const jobs=E.relicHuntOverview(state,venue).jobs.filter(q=>q.status==='active'&&(q.canRecover||q.origin===state.location&&q.venue===venue));if(!jobs.length)return '';return `<section class="relic-leads"><h3>Relic leads</h3>${jobs.map(q=>`<article class="service-card"><strong>${esc(q.name)}</strong><p>${esc(q.progressText)} · No deadline</p><div class="actions">${q.canRecover?btn('Restore instrument · 1 day','relic-hunt-recover',`data-id="${q.id}"`):''}${q.canComplete?btn('Claim relic','relic-hunt-complete',`data-id="${q.id}" data-venue="${q.venue}"`):''}</div></article>`).join('')}</section>`;}
function secretJobsPanel(actions=true){const jobs=E.underworldOverview(state).quests.filter(q=>q.status==='active');if(!jobs.length)return '';return `<section><h3>Secret commissions</h3>${jobs.map(q=>`<article class="card"><h3>${esc(q.title)} · ${esc(q.status)}</h3><p class="small muted">${esc(stationLabel(q.origin||q.originName))} → ${esc(stationLabel(q.target||q.targetName))}</p>${q.status==='active'?`<p>${esc(objectiveText(q.description))}</p><p><strong>No deadline</strong><br>${esc(objectiveText(q.progress))}</p><p>Reward: ${fmt(q.reward)} cr + ${esc(q.relicName)}</p>${actions?`<div class="actions">${q.canRecover?btn('Recover survey archive','secret-operation',`data-type="secret-recover" data-id="${q.id}"`):''}${q.canComplete?btn('Complete secret job','secret-operation',`data-type="secret-complete" data-id="${q.id}"`):''}${btn('Abandon secret job…','secret-abandon-prompt',`data-id="${q.id}"`)}</div>`:'<p class="small muted">Visit a local canteen for recovery and handover.</p>'}`:''}</article>`).join('')}</section>`;}
function canteenSecretsPanel(){const u=E.underworldOverview(state),c=u.contact;return `${c?`<article class="card"><h3>A quiet table</h3><div class="market-item-heading">${portraitSVG(c.host,64)}<div><strong>${esc(c.host.person)}</strong><p>${esc(c.host.role)}<br><small>Staying through day ${c.ends}</small></p></div></div>${c.node==='hidden'?`<p>An unfamiliar traveller watches the room. A visit may bring an opportunity; it may bring trouble.</p>${btn('Join '+esc(c.host.person),'secret-talk',`data-key="${c.key}" data-choice="intro"`,false,'primary')}`:`${exchangeHTML('secret',conversationVisit+':'+c.key+':'+c.node+':'+c.response,c.response,c.host,travellerConversationReplies(c),travellerConversationDecision(c),c.key)}${c.relic?`<h3>${esc(c.relic.name)}</h3><p>${esc(c.relic.lore)}</p><p>${esc(c.relic.detail)}</p>${btn(c.relic.available?'Buy relic · '+fmt(c.relic.buy)+' cr':'Relic unavailable or already owned','secret-relic-prompt',`data-key="${c.key}" data-id="${c.relic.id}" data-kind="buy-relic"`,!c.relic.available||state.credits<c.relic.buy,'primary')}`:''}${c.screening?.length?customsPackingPanel(c.key):''}${c.buybacks.map(r=>btn('Sell '+esc(r.name)+' · '+fmt(r.price)+' cr','secret-relic-prompt',`data-key="${c.key}" data-id="${r.id}" data-kind="sell-relic"`)).join('')}${c.good?`<h3>${esc(c.good.name)}</h3><p class="${c.good.illegal?'warning':'muted'}">${c.good.illegal?'Restricted cargo · normal arrival inspections apply':'Legal merchandise'}</p><p>Stock ${c.good.stock} · buyer capacity ${c.good.demand} · aboard ${c.good.aboard}<br>Buy ${fmt(c.good.buy)} cr · sell ${fmt(c.good.sell)} cr per unit</p><div class="actions">${btn('Buy 1','secret-goods',`data-key="${c.key}" data-id="${c.good.id}" data-kind="buy"`,c.good.stock<1||E.cargoRoom(state,c.good.id)<1||state.credits<c.good.buy)}${btn('Sell 1','secret-goods',`data-key="${c.key}" data-id="${c.good.id}" data-kind="sell"`,c.good.demand<1||c.good.aboard<1)}</div><p class="small muted">Fixed negotiated prices for this visit. Each lot contains 250 kg net; packaging adds weight and volume. Client freight cannot be sold.</p>`:''}`}</article>`:''}${secretJobsPanel(true)}`;}

document.addEventListener('keydown',e=>{if(e.target.matches('[data-bank-amount]')&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();stepBankAmount(e.key==='ArrowUp'?1000:-1000,e.target.dataset.bankScope);}});

function careerCommunicationsPanel(){const o=E.careerDevelopment(state),letters=o.mail,works=o.mastery.filter(j=>j.status==='active'||j.status==='available'&&j.ready);careerMailPage=Math.min(careerMailPage,Math.max(0,Math.ceil(letters.length/8)-1));return `${letters.length?`<section class="career-correspondence"><h3>Correspondence</h3>${letters.slice(careerMailPage*8,careerMailPage*8+8).map(l=>`<article class="service-choice"><h4>${esc(l.person)}</h4><p>${esc(stationLabel(l.port))} · ${esc(l.title)}</p><div class="actions">${l.choice?['evidence','people','autonomy'].map(k=>btn(E.careerLetterReply(k),'career-letter',`data-id="${esc(l.id)}" data-position="${k}"`)).join(''):btn('Read account','career-letter',`data-id="${esc(l.id)}"`)}</div></article>`).join('')}${letters.length>8?`<div class="actions">${btn('Previous','career-mail-page','data-delta="-1"',!careerMailPage)}${btn('Next','career-mail-page','data-delta="1"',(careerMailPage+1)*8>=letters.length)}</div>`:''}</section>`:''}${works.length?`<section class="career-mastery"><h3>Professional development</h3>${works.map(j=>`<article class="service-choice"><h4>${esc(j.title)}</h4>${j.status==='active'?`<p>${esc(j.progress)}</p><div class="actions">${!j.canComplete&&state.location===j.target?btn('Hear receiving account','career-mastery',`data-id="${esc(j.id)}" data-operation="receive"`,state.careerDevelopment?.mastery.find(x=>x.id===j.id)?.received):''}${j.canComplete?btn('Report completed work','career-mastery',`data-id="${esc(j.id)}" data-operation="complete"`):''}${state.location!==j.nextPort?btn('Plot '+esc(stationLabel(j.nextPort)),'plot',`data-id="${esc(j.nextPort)}"`):''}</div>`:`<p>Demonstrate new work and hear a receiving account. No deadline.</p>${btn('Begin undertaking','career-mastery',`data-id="${esc(j.id)}" data-operation="accept"`)}`}</article>`).join('')}</section>`:''}`;}
